'use client';

import { useState, useEffect } from 'react';
import { useAuth } from '@/lib/AuthContext';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/Button';

interface Tree {
    id: string;
    name: string;
    price: number;
    category: string;
    images: string[];
    stock: number;
    isPromotion: boolean;
    originalPrice: number | null;
    promotionName: string | null;
    promotionEndDate: string | null;
}

type DiscountType = 'percent' | 'fixed';

export default function AdminPromotionsPage() {
    const { user, isLoading } = useAuth();
    const router = useRouter();
    const [trees, setTrees] = useState<Tree[]>([]);
    const [search, setSearch] = useState('');
    const [categoryFilter, setCategoryFilter] = useState('all');
    const [selected, setSelected] = useState<Set<string>>(new Set());
    const [showModal, setShowModal] = useState(false);
    const [isBulk, setIsBulk] = useState(false);
    const [editingTree, setEditingTree] = useState<Tree | null>(null);

    // Form state
    const [discountType, setDiscountType] = useState<DiscountType>('percent');
    const [discountValue, setDiscountValue] = useState<number>(0);
    const [promoName, setPromoName] = useState('');
    const [promoEndDate, setPromoEndDate] = useState('');
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        if (!isLoading && (!user || user.role !== 'admin')) {
            router.push('/login');
        } else if (user?.role === 'admin') {
            fetchTrees();
        }
    }, [user, isLoading, router]);

    const fetchTrees = async () => {
        try {
            const res = await fetch('/api/trees');
            if (res.ok) {
                const data = await res.json();
                setTrees(data);
            }
        } catch (error) {
            console.error('Failed to fetch trees:', error);
        }
    };

    // Extract unique categories
    const categories = Array.from(new Set(trees.map(t => t.category))).sort();

    const filteredTrees = trees.filter(t => {
        const matchSearch = t.name.toLowerCase().includes(search.toLowerCase()) ||
            t.category.toLowerCase().includes(search.toLowerCase());
        const matchCategory = categoryFilter === 'all' || t.category === categoryFilter;
        return matchSearch && matchCategory;
    });

    const toggleSelect = (id: string) => {
        setSelected(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    const toggleSelectAll = () => {
        if (selected.size === filteredTrees.length) {
            setSelected(new Set());
        } else {
            setSelected(new Set(filteredTrees.map(t => t.id)));
        }
    };

    const openSingleEdit = (tree: Tree) => {
        setEditingTree(tree);
        setIsBulk(false);
        setDiscountType('percent');
        setDiscountValue(tree.isPromotion && tree.originalPrice ? Math.round((1 - tree.price / tree.originalPrice) * 100) : 0);
        setPromoName(tree.promotionName || '');
        setPromoEndDate(tree.promotionEndDate ? tree.promotionEndDate.split('T')[0] : '');
        setShowModal(true);
    };

    const openBulkEdit = () => {
        if (selected.size === 0) return;
        setEditingTree(null);
        setIsBulk(true);
        setDiscountType('percent');
        setDiscountValue(0);
        setPromoName('');
        setPromoEndDate('');
        setShowModal(true);
    };

    const handleSave = async () => {
        setSaving(true);
        const storedUser = localStorage.getItem('khun_daeng_user');
        const userId = storedUser ? JSON.parse(storedUser).id : null;

        const treeIds = isBulk ? Array.from(selected) : (editingTree ? [editingTree.id] : []);

        try {
            for (const id of treeIds) {
                const tree = trees.find(t => t.id === id);
                if (!tree) continue;

                const currentOriginalPrice = tree.isPromotion && tree.originalPrice ? tree.originalPrice : tree.price;
                let newPrice: number;

                if (discountType === 'percent') {
                    newPrice = Math.round(currentOriginalPrice * (1 - discountValue / 100));
                } else {
                    newPrice = discountValue;
                }

                await fetch(`/api/trees/${id}`, {
                    method: 'PUT',
                    headers: {
                        'Content-Type': 'application/json',
                        ...(userId ? { 'x-user-id': userId } : {})
                    },
                    body: JSON.stringify({
                        isPromotion: true,
                        originalPrice: currentOriginalPrice,
                        price: newPrice,
                        promotionName: promoName || null,
                        promotionEndDate: promoEndDate || null
                    })
                });
            }

            await fetchTrees();
            setShowModal(false);
            setSelected(new Set());
        } catch (error) {
            console.error('Error saving promotion:', error);
            alert('เกิดข้อผิดพลาดในการบันทึก');
        } finally {
            setSaving(false);
        }
    };

    const handleRemovePromotion = async (tree: Tree) => {
        if (!confirm(`ยกเลิกโปรโมชัน "${tree.name}" ?`)) return;

        const storedUser = localStorage.getItem('khun_daeng_user');
        const userId = storedUser ? JSON.parse(storedUser).id : null;

        try {
            await fetch(`/api/trees/${tree.id}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    ...(userId ? { 'x-user-id': userId } : {})
                },
                body: JSON.stringify({
                    isPromotion: false,
                    price: tree.originalPrice || tree.price,
                    originalPrice: null,
                    promotionName: null,
                    promotionEndDate: null
                })
            });
            await fetchTrees();
        } catch (error) {
            console.error('Error removing promotion:', error);
        }
    };

    const handleBulkRemovePromotion = async () => {
        if (selected.size === 0) return;
        if (!confirm(`ยกเลิกโปรโมชันสำหรับ ${selected.size} รายการ?`)) return;

        const storedUser = localStorage.getItem('khun_daeng_user');
        const userId = storedUser ? JSON.parse(storedUser).id : null;

        for (const id of selected) {
            const tree = trees.find(t => t.id === id);
            if (!tree || !tree.isPromotion) continue;

            await fetch(`/api/trees/${id}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    ...(userId ? { 'x-user-id': userId } : {})
                },
                body: JSON.stringify({
                    isPromotion: false,
                    price: tree.originalPrice || tree.price,
                    originalPrice: null,
                    promotionName: null,
                    promotionEndDate: null
                })
            });
        }

        await fetchTrees();
        setSelected(new Set());
    };

    const getDiscountPercent = (tree: Tree) => {
        if (!tree.isPromotion || !tree.originalPrice || tree.originalPrice <= tree.price) return null;
        return Math.round((1 - tree.price / tree.originalPrice) * 100);
    };

    if (isLoading || !user) return <div style={{ padding: '2rem' }}>Loading...</div>;

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '1rem' }}>
                <h1 style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#1f2937' }}>จัดการโปรโมชัน</h1>
                <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                    {selected.size > 0 && (
                        <>
                            <Button onClick={openBulkEdit} style={{ backgroundColor: '#dc2626', color: 'white' }}>
                                🏷️ ตั้งโปรโมชัน {selected.size} รายการ
                            </Button>
                            <Button onClick={handleBulkRemovePromotion} variant="outline" style={{ borderColor: '#dc2626', color: '#dc2626' }}>
                                ยกเลิกโปร {selected.size} รายการ
                            </Button>
                        </>
                    )}
                </div>
            </div>

            {/* Search + Category Filter */}
            <div style={{ display: 'flex', gap: '0.75rem', marginBottom: '1rem', flexWrap: 'wrap', alignItems: 'center' }}>
                <input
                    type="text"
                    placeholder="🔍 ค้นหาต้นไม้..."
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                    style={{
                        flex: '1 1 200px',
                        maxWidth: '300px',
                        padding: '0.75rem',
                        border: '1px solid #d1d5db',
                        borderRadius: '0.5rem',
                        fontSize: '0.875rem'
                    }}
                />
                <select
                    value={categoryFilter}
                    onChange={e => { setCategoryFilter(e.target.value); setSelected(new Set()); }}
                    style={{
                        padding: '0.75rem',
                        border: '1px solid #d1d5db',
                        borderRadius: '0.5rem',
                        fontSize: '0.875rem',
                        backgroundColor: 'white',
                        cursor: 'pointer',
                        minWidth: '180px'
                    }}
                >
                    <option value="all">📦 ทุกหมวดหมู่</option>
                    {categories.map(cat => (
                        <option key={cat} value={cat}>{cat} ({trees.filter(t => t.category === cat).length})</option>
                    ))}
                </select>
                {categoryFilter !== 'all' && (
                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                        <button
                            onClick={() => {
                                const catTrees = filteredTrees.map(t => t.id);
                                setSelected(new Set(catTrees));
                            }}
                            style={{
                                padding: '0.5rem 1rem',
                                backgroundColor: '#e0f2fe',
                                color: '#0369a1',
                                border: '1px solid #7dd3fc',
                                borderRadius: '0.5rem',
                                cursor: 'pointer',
                                fontSize: '0.8rem',
                                fontWeight: 'bold'
                            }}
                        >
                            ☑️ เลือกทั้งหมวด หมู่{categoryFilter}
                        </button>
                    </div>
                )}
            </div>

            {/* Summary */}
            <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
                <div style={{ padding: '1rem 1.5rem', backgroundColor: '#dcfce7', borderRadius: '0.5rem', flex: '1 1 150px', textAlign: 'center' }}>
                    <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#166534' }}>{trees.length}</div>
                    <div style={{ fontSize: '0.75rem', color: '#166534' }}>สินค้าทั้งหมด</div>
                </div>
                <div style={{ padding: '1rem 1.5rem', backgroundColor: '#fee2e2', borderRadius: '0.5rem', flex: '1 1 150px', textAlign: 'center' }}>
                    <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#991b1b' }}>{trees.filter(t => t.isPromotion).length}</div>
                    <div style={{ fontSize: '0.75rem', color: '#991b1b' }}>กำลังลดราคา</div>
                </div>
                <div style={{ padding: '1rem 1.5rem', backgroundColor: '#f3f4f6', borderRadius: '0.5rem', flex: '1 1 150px', textAlign: 'center' }}>
                    <div style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#374151' }}>{trees.filter(t => !t.isPromotion).length}</div>
                    <div style={{ fontSize: '0.75rem', color: '#374151' }}>ราคาปกติ</div>
                </div>
            </div>

            <style dangerouslySetInnerHTML={{
                __html: `
                .desktop-table-view { display: none; }
                .mobile-card-view { display: flex; flex-direction: column; gap: 1rem; padding-bottom: 2rem; }
                @media (min-width: 768px) {
                    .desktop-table-view { display: block; }
                    .mobile-card-view { display: none; }
                }
            `}} />

            {/* Mobile View (Cards) */}
            <div className="mobile-card-view">
                <div style={{ padding: '1rem', backgroundColor: '#f9fafb', borderRadius: '0.5rem', border: '1px solid #e5e7eb', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <input type="checkbox" checked={selected.size === filteredTrees.length && filteredTrees.length > 0} onChange={toggleSelectAll} id="selectAllMobile" />
                    <label htmlFor="selectAllMobile" style={{ fontWeight: 500 }}>เลือกทั้งหมด</label>
                </div>
                {filteredTrees.map(tree => {
                    const discount = getDiscountPercent(tree);
                    let imageUrl = '/placeholder-tree.jpg';
                    try { if (tree.images && tree.images.length > 0) imageUrl = tree.images[0]; } catch { }

                    return (
                        <div key={tree.id} style={{
                            border: '1px solid #e5e7eb',
                            borderRadius: '0.75rem',
                            padding: '1rem',
                            backgroundColor: selected.has(tree.id) ? '#fef3c7' : 'white',
                            display: 'flex',
                            flexDirection: 'column',
                            gap: '0.75rem'
                        }}>
                            <div style={{ display: 'flex', gap: '1rem', alignItems: 'flex-start' }}>
                                <input type="checkbox" checked={selected.has(tree.id)} onChange={() => toggleSelect(tree.id)} style={{ marginTop: '0.25rem' }} />
                                <div style={{ width: '60px', height: '60px', borderRadius: '8px', overflow: 'hidden', backgroundColor: '#f3f4f6', flexShrink: 0 }}>
                                    <img src={imageUrl} alt={tree.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                </div>
                                <div style={{ flex: 1 }}>
                                    <div style={{ fontWeight: 'bold' }}>{tree.name}</div>
                                    <div style={{ fontSize: '0.875rem', color: '#6b7280' }}>
                                        {tree.category} • <span style={{ color: tree.isPromotion ? '#166534' : '#9ca3af' }}>{tree.isPromotion ? 'เปิดโปร' : 'ปกติ'}</span>
                                    </div>
                                    <div style={{ marginTop: '0.25rem', display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap' }}>
                                        <span style={{ fontWeight: 'bold', color: tree.isPromotion ? '#dc2626' : '#1f2937' }}>
                                            ฿{tree.price.toLocaleString()}
                                        </span>
                                        {tree.isPromotion && (
                                            <>
                                                <span style={{ textDecoration: 'line-through', color: '#6b7280', fontSize: '0.875rem' }}>
                                                    ฿{(tree.originalPrice || tree.price).toLocaleString()}
                                                </span>
                                                {discount && (
                                                    <span style={{ backgroundColor: '#fee2e2', color: '#dc2626', padding: '0.125rem 0.5rem', borderRadius: '9999px', fontSize: '0.75rem', fontWeight: 'bold' }}>
                                                        -{discount}%
                                                    </span>
                                                )}
                                            </>
                                        )}
                                    </div>
                                </div>
                            </div>
                            <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.25rem' }}>
                                <button
                                    onClick={() => openSingleEdit(tree)}
                                    style={{
                                        flex: 1, padding: '0.5rem', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '0.375rem', cursor: 'pointer', fontSize: '0.875rem', fontWeight: 500
                                    }}
                                >
                                    🏷️ ตั้งโปร
                                </button>
                                {tree.isPromotion && (
                                    <button
                                        onClick={() => handleRemovePromotion(tree)}
                                        style={{
                                            flex: 1, padding: '0.5rem', backgroundColor: '#f3f4f6', color: '#6b7280', border: '1px solid #d1d5db', borderRadius: '0.375rem', cursor: 'pointer', fontSize: '0.875rem', fontWeight: 500
                                        }}
                                    >
                                        ยกเลิก
                                    </button>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Desktop View (Table) */}
            <div className="desktop-table-view">
                <div style={{ maxWidth: '100vw', overflowX: 'auto', WebkitOverflowScrolling: 'touch', paddingBottom: '1rem' }}>
                    <div style={{ backgroundColor: 'white', borderRadius: '0.75rem', border: '1px solid #e5e7eb', minWidth: '800px' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.875rem' }}>
                            <thead>
                                <tr style={{ backgroundColor: '#f9fafb', borderBottom: '1px solid #e5e7eb' }}>
                                    <th style={{ padding: '0.75rem', textAlign: 'center', width: '40px' }}>
                                        <input type="checkbox" checked={selected.size === filteredTrees.length && filteredTrees.length > 0} onChange={toggleSelectAll} />
                                    </th>
                                    <th style={{ padding: '0.75rem', textAlign: 'left' }}>รูป</th>
                                    <th style={{ padding: '0.75rem', textAlign: 'left' }}>ชื่อ</th>
                                    <th style={{ padding: '0.75rem', textAlign: 'left' }}>หมวดหมู่</th>
                                    <th style={{ padding: '0.75rem', textAlign: 'right' }}>ราคาเดิม</th>
                                    <th style={{ padding: '0.75rem', textAlign: 'right' }}>ราคาขาย</th>
                                    <th style={{ padding: '0.75rem', textAlign: 'center' }}>ส่วนลด</th>
                                    <th style={{ padding: '0.75rem', textAlign: 'center' }}>สถานะ</th>
                                    <th style={{ padding: '0.75rem', textAlign: 'center' }}>จัดการ</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredTrees.map(tree => {
                                    const discount = getDiscountPercent(tree);
                                    let imageUrl = '/placeholder-tree.jpg';
                                    try {
                                        if (tree.images && tree.images.length > 0) imageUrl = tree.images[0];
                                    } catch { }

                                    return (
                                        <tr key={tree.id} style={{
                                            borderBottom: '1px solid #e5e7eb',
                                            backgroundColor: selected.has(tree.id) ? '#fef3c7' : 'transparent'
                                        }}>
                                            <td style={{ padding: '0.75rem', textAlign: 'center' }}>
                                                <input type="checkbox" checked={selected.has(tree.id)} onChange={() => toggleSelect(tree.id)} />
                                            </td>
                                            <td style={{ padding: '0.5rem' }}>
                                                <div style={{ width: '45px', height: '45px', borderRadius: '8px', overflow: 'hidden', backgroundColor: '#f3f4f6' }}>
                                                    <img src={imageUrl} alt={tree.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                                </div>
                                            </td>
                                            <td style={{ padding: '0.75rem', fontWeight: '500' }}>{tree.name}</td>
                                            <td style={{ padding: '0.75rem', color: '#6b7280' }}>{tree.category}</td>
                                            <td style={{ padding: '0.75rem', textAlign: 'right', color: '#6b7280', textDecoration: tree.isPromotion ? 'line-through' : 'none' }}>
                                                ฿{(tree.isPromotion && tree.originalPrice ? tree.originalPrice : tree.price).toLocaleString()}
                                            </td>
                                            <td style={{ padding: '0.75rem', textAlign: 'right', fontWeight: 'bold', color: tree.isPromotion ? '#dc2626' : '#1f2937' }}>
                                                ฿{tree.price.toLocaleString()}
                                            </td>
                                            <td style={{ padding: '0.75rem', textAlign: 'center' }}>
                                                {discount ? (
                                                    <span style={{
                                                        backgroundColor: '#fee2e2',
                                                        color: '#dc2626',
                                                        padding: '0.25rem 0.75rem',
                                                        borderRadius: '9999px',
                                                        fontSize: '0.75rem',
                                                        fontWeight: 'bold'
                                                    }}>-{discount}%</span>
                                                ) : (
                                                    <span style={{ color: '#9ca3af' }}>—</span>
                                                )}
                                            </td>
                                            <td style={{ padding: '0.75rem', textAlign: 'center' }}>
                                                <span style={{
                                                    display: 'inline-block',
                                                    width: '10px',
                                                    height: '10px',
                                                    borderRadius: '50%',
                                                    backgroundColor: tree.isPromotion ? '#16a34a' : '#d1d5db',
                                                    marginRight: '0.25rem'
                                                }}></span>
                                                <span style={{ fontSize: '0.75rem', color: tree.isPromotion ? '#166534' : '#9ca3af' }}>
                                                    {tree.isPromotion ? 'เปิดโปร' : 'ปกติ'}
                                                </span>
                                            </td>
                                            <td style={{ padding: '0.75rem', textAlign: 'center' }}>
                                                <div style={{ display: 'flex', gap: '0.25rem', justifyContent: 'center' }}>
                                                    <button
                                                        onClick={() => openSingleEdit(tree)}
                                                        style={{
                                                            padding: '0.375rem 0.75rem',
                                                            backgroundColor: '#dc2626',
                                                            color: 'white',
                                                            border: 'none',
                                                            borderRadius: '0.375rem',
                                                            cursor: 'pointer',
                                                            fontSize: '0.75rem'
                                                        }}
                                                    >
                                                        🏷️ ตั้งโปร
                                                    </button>
                                                    {tree.isPromotion && (
                                                        <button
                                                            onClick={() => handleRemovePromotion(tree)}
                                                            style={{
                                                                padding: '0.375rem 0.75rem',
                                                                backgroundColor: '#f3f4f6',
                                                                color: '#6b7280',
                                                                border: '1px solid #d1d5db',
                                                                borderRadius: '0.375rem',
                                                                cursor: 'pointer',
                                                                fontSize: '0.75rem'
                                                            }}
                                                        >
                                                            ยกเลิก
                                                        </button>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {/* Modal */}
            {showModal && (
                <div style={{
                    position: 'fixed',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    backgroundColor: 'rgba(0,0,0,0.5)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    zIndex: 99999
                }} onClick={() => setShowModal(false)}>
                    <div style={{
                        backgroundColor: 'white',
                        borderRadius: '1rem',
                        padding: '0',
                        maxWidth: '500px',
                        width: '90%',
                        maxHeight: 'calc(100vh - 160px)',
                        display: 'flex',
                        flexDirection: 'column',
                        overflow: 'hidden'
                    }} onClick={e => e.stopPropagation()}>
                        <div style={{ padding: '2rem 2rem 0', overflowY: 'auto', flex: 1 }}>
                            <h2 style={{ fontSize: '1.25rem', fontWeight: 'bold', marginBottom: '1.5rem' }}>
                                {isBulk ? `🏷️ ตั้งโปรโมชัน ${selected.size} รายการ` : `🏷️ ตั้งโปรโมชัน: ${editingTree?.name}`}
                            </h2>

                            <div style={{ display: 'grid', gap: '1.25rem' }}>
                                {/* Discount Type */}
                                <div>
                                    <label style={{ display: 'block', fontWeight: 'bold', fontSize: '0.875rem', marginBottom: '0.5rem' }}>ประเภทส่วนลด</label>
                                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                                        <button
                                            onClick={() => { setDiscountType('percent'); setDiscountValue(0); }}
                                            style={{
                                                flex: 1,
                                                padding: '0.75rem',
                                                borderRadius: '0.5rem',
                                                border: discountType === 'percent' ? '2px solid #dc2626' : '1px solid #d1d5db',
                                                backgroundColor: discountType === 'percent' ? '#fee2e2' : 'white',
                                                color: discountType === 'percent' ? '#dc2626' : '#374151',
                                                fontWeight: 'bold',
                                                cursor: 'pointer'
                                            }}
                                        >
                                            ลดเป็น %
                                        </button>
                                        <button
                                            onClick={() => { setDiscountType('fixed'); setDiscountValue(0); }}
                                            style={{
                                                flex: 1,
                                                padding: '0.75rem',
                                                borderRadius: '0.5rem',
                                                border: discountType === 'fixed' ? '2px solid #dc2626' : '1px solid #d1d5db',
                                                backgroundColor: discountType === 'fixed' ? '#fee2e2' : 'white',
                                                color: discountType === 'fixed' ? '#dc2626' : '#374151',
                                                fontWeight: 'bold',
                                                cursor: 'pointer'
                                            }}
                                        >
                                            ราคาต่อชิ้น (฿)
                                        </button>
                                    </div>
                                </div>

                                {/* Discount Value */}
                                <div>
                                    <label style={{ display: 'block', fontWeight: 'bold', fontSize: '0.875rem', marginBottom: '0.5rem' }}>
                                        {discountType === 'percent' ? 'ส่วนลด (%)' : 'ราคาขาย (บาท)'}
                                    </label>
                                    <div style={{ position: 'relative' }}>
                                        <input
                                            type="number"
                                            value={discountValue || ''}
                                            onChange={e => setDiscountValue(Number(e.target.value))}
                                            min={0}
                                            max={discountType === 'percent' ? 99 : undefined}
                                            placeholder={discountType === 'percent' ? 'เช่น 20' : 'เช่น 250'}
                                            style={{
                                                width: '100%',
                                                padding: '0.75rem',
                                                paddingRight: '3rem',
                                                border: '1px solid #d1d5db',
                                                borderRadius: '0.5rem',
                                                fontSize: '1.25rem',
                                                fontWeight: 'bold'
                                            }}
                                        />
                                        <span style={{
                                            position: 'absolute',
                                            right: '1rem',
                                            top: '50%',
                                            transform: 'translateY(-50%)',
                                            color: '#6b7280',
                                            fontWeight: 'bold',
                                            fontSize: '1.25rem'
                                        }}>
                                            {discountType === 'percent' ? '%' : '฿'}
                                        </span>
                                    </div>

                                    {/* Preview */}
                                    {!isBulk && editingTree && discountValue > 0 && (
                                        <div style={{ marginTop: '0.5rem', padding: '0.75rem', backgroundColor: '#fef3c7', borderRadius: '0.5rem', fontSize: '0.875rem' }}>
                                            {discountType === 'percent' ? (
                                                <>ราคาเดิม ฿{(editingTree.originalPrice || editingTree.price).toLocaleString()} → <strong style={{ color: '#dc2626' }}>฿{Math.round((editingTree.originalPrice || editingTree.price) * (1 - discountValue / 100)).toLocaleString()}</strong></>
                                            ) : (
                                                <>ราคาเดิม ฿{(editingTree.originalPrice || editingTree.price).toLocaleString()} → <strong style={{ color: '#dc2626' }}>฿{discountValue.toLocaleString()}</strong> (ลด {Math.round((1 - discountValue / (editingTree.originalPrice || editingTree.price)) * 100)}%)</>
                                            )}
                                        </div>
                                    )}
                                </div>

                                {/* Promotion Name */}
                                <div>
                                    <label style={{ display: 'block', fontWeight: 'bold', fontSize: '0.875rem', marginBottom: '0.5rem' }}>ชื่อโปรโมชัน (ไม่บังคับ)</label>
                                    <input
                                        type="text"
                                        value={promoName}
                                        onChange={e => setPromoName(e.target.value)}
                                        placeholder="เช่น Valentine Sale, ลดกระหน่ำ"
                                        style={{
                                            width: '100%',
                                            padding: '0.75rem',
                                            border: '1px solid #d1d5db',
                                            borderRadius: '0.5rem'
                                        }}
                                    />
                                </div>

                                {/* End Date */}
                                <div>
                                    <label style={{ display: 'block', fontWeight: 'bold', fontSize: '0.875rem', marginBottom: '0.5rem' }}>วันหมดอายุโปร (ไม่บังคับ)</label>
                                    <input
                                        type="date"
                                        value={promoEndDate}
                                        onChange={e => setPromoEndDate(e.target.value)}
                                        style={{
                                            width: '100%',
                                            padding: '0.75rem',
                                            border: '1px solid #d1d5db',
                                            borderRadius: '0.5rem'
                                        }}
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Actions - sticky at bottom */}
                        <div style={{ display: 'flex', gap: '0.75rem', padding: '1rem 2rem 1.5rem', justifyContent: 'flex-end', borderTop: '1px solid #e5e7eb', backgroundColor: 'white', borderBottomLeftRadius: '1rem', borderBottomRightRadius: '1rem', flexShrink: 0 }}>
                            <Button variant="outline" onClick={() => setShowModal(false)} disabled={saving}>ยกเลิก</Button>
                            <Button
                                onClick={handleSave}
                                disabled={saving}
                                style={{ backgroundColor: '#dc2626', color: 'white' }}
                            >
                                {saving ? 'กำลังบันทึก...' : '✅ บันทึกโปรโมชัน'}
                            </Button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/AuthContext';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';

interface Review {
    id: string;
    rating: number;
    comment: string | null;
    images: string | null;
    hidden: boolean;
    helpful: number;
    createdAt: string;
    user: { id: string; firstName: string; lastName: string; email: string };
    tree: { id: string; name: string; images: string };
}

export default function AdminReviewsPage() {
    const router = useRouter();
    const { user, isLoading: isAuthLoading } = useAuth();
    const [reviews, setReviews] = useState<Review[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [filter, setFilter] = useState<'all' | 'visible' | 'hidden'>('all');

    useEffect(() => {
        if (isAuthLoading) return;
        if (!user || user.role !== 'admin') {
            router.push('/admin/login');
            return;
        }
        fetchReviews();
    }, [user, isAuthLoading, router]);

    const fetchReviews = async () => {
        try {
            const res = await fetch('/api/admin/reviews');
            if (res.ok) {
                const data = await res.json();
                setReviews(data);
            }
        } catch (error) {
            console.error('Failed to fetch reviews', error);
        } finally {
            setIsLoading(false);
        }
    };

    const toggleHidden = async (reviewId: string, hidden: boolean) => {
        try {
            const res = await fetch(`/api/admin/reviews/${reviewId}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ hidden: !hidden })
            });
            if (res.ok) {
                setReviews(prev =>
                    prev.map(r => r.id === reviewId ? { ...r, hidden: !hidden } : r)
                );
            }
        } catch (error) {
            console.error('Failed to toggle review visibility', error);
        }
    };

    const deleteReview = async (reviewId: string) => {
        if (!confirm('คุณแน่ใจหรือไม่ที่จะลบรีวิวนี้? การลบจะไม่สามารถกู้คืนได้')) return;
        try {
            const res = await fetch(`/api/admin/reviews/${reviewId}`, { method: 'DELETE' });
            if (res.ok) {
                setReviews(prev => prev.filter(r => r.id !== reviewId));
            }
        } catch (error) {
            console.error('Failed to delete review', error);
        }
    };

    const filteredReviews = reviews.filter(r => {
        if (filter === 'visible') return !r.hidden;
        if (filter === 'hidden') return r.hidden;
        return true;
    });

    const renderStars = (rating: number) => {
        return '★'.repeat(rating) + '☆'.repeat(5 - rating);
    };

    if (isAuthLoading) {
        return <div style={{ padding: '4rem', textAlign: 'center' }}>กำลังโหลด...</div>;
    }

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
                <h1 style={{ fontSize: '2rem', fontWeight: 'bold' }}>จัดการรีวิว (Reviews)</h1>
                <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <span style={{ fontSize: '0.875rem', color: '#6b7280', alignSelf: 'center' }}>
                        ทั้งหมด {reviews.length} รีวิว | ซ่อนอยู่ {reviews.filter(r => r.hidden).length}
                    </span>
                </div>
            </div>

            {/* Filter tabs */}
            <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem' }}>
                {(['all', 'visible', 'hidden'] as const).map(f => (
                    <button
                        key={f}
                        onClick={() => setFilter(f)}
                        style={{
                            padding: '0.5rem 1rem',
                            borderRadius: '9999px',
                            border: 'none',
                            cursor: 'pointer',
                            fontWeight: filter === f ? 'bold' : 'normal',
                            backgroundColor: filter === f ? '#059669' : '#f3f4f6',
                            color: filter === f ? 'white' : '#374151',
                            transition: 'all 0.2s'
                        }}
                    >
                        {f === 'all' ? 'ทั้งหมด' : f === 'visible' ? '🟢 แสดงอยู่' : '🔴 ซ่อนอยู่'}
                    </button>
                ))}
            </div>

            {isLoading ? (
                <div style={{ textAlign: 'center', padding: '3rem' }}>กำลังโหลด...</div>
            ) : filteredReviews.length === 0 ? (
                <Card>
                    <CardContent style={{ padding: '3rem', textAlign: 'center' }}>
                        <p style={{ color: '#6b7280' }}>ไม่พบรีวิว</p>
                    </CardContent>
                </Card>
            ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                    {filteredReviews.map(review => {
                        let treeImage = '/placeholder-tree.jpg';
                        try {
                            const imgs = JSON.parse(review.tree.images);
                            if (imgs.length > 0) treeImage = imgs[0];
                        } catch { }

                        return (
                            <Card key={review.id} style={{
                                opacity: review.hidden ? 0.6 : 1,
                                borderLeft: `4px solid ${review.hidden ? '#ef4444' : '#22c55e'}`
                            }}>
                                <CardContent style={{ padding: '1.25rem' }}>
                                    <div style={{ display: 'grid', gridTemplateColumns: '60px 1fr auto', gap: '1rem', alignItems: 'start' }}>
                                        {/* Tree image */}
                                        <img
                                            src={treeImage}
                                            alt={review.tree.name}
                                            style={{ width: '60px', height: '60px', objectFit: 'cover', borderRadius: '0.5rem' }}
                                        />

                                        {/* Review content */}
                                        <div>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.25rem' }}>
                                                <span style={{ fontWeight: 'bold' }}>{review.user.firstName} {review.user.lastName}</span>
                                                <span style={{ color: '#f59e0b', fontSize: '1rem' }}>{renderStars(review.rating)}</span>
                                                {review.hidden && (
                                                    <span style={{
                                                        backgroundColor: '#fee2e2',
                                                        color: '#dc2626',
                                                        padding: '0.125rem 0.5rem',
                                                        borderRadius: '9999px',
                                                        fontSize: '0.75rem',
                                                        fontWeight: 'bold'
                                                    }}>ซ่อนอยู่</span>
                                                )}
                                            </div>
                                            <p style={{ fontSize: '0.75rem', color: '#6b7280', marginBottom: '0.5rem' }}>
                                                ต้นไม้: {review.tree.name} | {new Date(review.createdAt).toLocaleDateString('th-TH')}
                                            </p>
                                            {review.comment && (
                                                <p style={{ color: '#374151', marginBottom: '0.5rem' }}>{review.comment}</p>
                                            )}
                                            {review.images && (() => {
                                                try {
                                                    const imgs = JSON.parse(review.images);
                                                    return (
                                                        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                                                            {imgs.map((img: string, i: number) => (
                                                                <img key={i} src={img} alt={`Review ${i}`} style={{ width: '60px', height: '60px', objectFit: 'cover', borderRadius: '0.25rem' }} />
                                                            ))}
                                                        </div>
                                                    );
                                                } catch { return null; }
                                            })()}
                                            <p style={{ fontSize: '0.75rem', color: '#9ca3af', marginTop: '0.25rem' }}>
                                                👍 {review.helpful} คนเห็นว่ามีประโยชน์
                                            </p>
                                        </div>

                                        {/* Actions */}
                                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                                            <Button
                                                size="sm"
                                                variant="outline"
                                                onClick={() => toggleHidden(review.id, review.hidden)}
                                                style={{
                                                    borderColor: review.hidden ? '#22c55e' : '#f59e0b',
                                                    color: review.hidden ? '#22c55e' : '#f59e0b',
                                                    fontSize: '0.75rem'
                                                }}
                                            >
                                                {review.hidden ? '👁 แสดง' : '🙈 ซ่อน'}
                                            </Button>
                                            <Button
                                                size="sm"
                                                variant="outline"
                                                onClick={() => deleteReview(review.id)}
                                                style={{ borderColor: '#ef4444', color: '#ef4444', fontSize: '0.75rem' }}
                                            >
                                                🗑 ลบ
                                            </Button>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/AuthContext';
import { Button } from '@/components/ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Input } from '@/components/ui/Input';
import { TagInput } from '@/components/TagInput';
import { SearchBar } from '@/components/admin/SearchBar';
import { SortableTableHeader } from '@/components/admin/SortableTableHeader';

interface Tree {
    id: string;
    name: string;
    description: string;
    price: number;
    category: string;
    status: string;
    images: string[];
    tags: string[];
    growthTime?: string;
    stock?: number;
    reserved?: number;
    sold?: number;
    isPromotion?: boolean;
    originalPrice?: number | null;
    promotionName?: string | null;
    promotionEndDate?: string | null;
}

export default function AdminTreesPage() {
    const router = useRouter();
    const { user, isLoading: isAuthLoading } = useAuth();
    const [trees, setTrees] = useState<Tree[]>([]);
    const [categories, setCategories] = useState<{ id: string, name: string }[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);

    // Category Modal State
    const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
    const [newCategoryName, setNewCategoryName] = useState('');

    const [editingTree, setEditingTree] = useState<Tree | null>(null);

    // Derived state for suggestions
    const allTags = Array.from(new Set(trees.flatMap(t => t.tags || [])));
    // allCategories is now replaced by 'categories' state

    // Form State
    const [formData, setFormData] = useState({
        name: '',
        description: '',
        price: 0,
        category: '',
        images: [] as string[],
        tags: [] as string[],
        growthTime: '',
        isPromotion: false,
        originalPrice: 0,
        promotionName: '',
        promotionEndDate: '',
        stock: 0
    });

    useEffect(() => {
        if (isAuthLoading) return;
        if (!user || user.role !== 'admin') {
            router.push('/admin/login');
            return;
        }
        fetchTrees();
        fetchCategories();
    }, [user, isAuthLoading, router]);

    const fetchCategories = async () => {
        try {
            const res = await fetch('/api/admin/categories');
            if (res.ok) {
                const data = await res.json();
                setCategories(data);
            }
        } catch (error) {
            console.error('Failed to fetch categories', error);
        }
    };

    const handleAddCategory = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            const res = await fetch('/api/admin/categories', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name: newCategoryName })
            });

            if (res.ok) {
                const newCat = await res.json();
                setCategories([...categories, newCat]);
                setFormData({ ...formData, category: newCat.name });
                setIsCategoryModalOpen(false);
                setNewCategoryName('');
            } else {
                const error = await res.json();
                alert(error.error || 'Failed to add category');
            }
        } catch (error) {
            console.error('Failed to add category', error);
            alert('Error adding category');
        }
    };

    // ... (rest of the file content until render)

    // Inside the Form render in Modal:
    /*
                                    <div>
                                        <label className="block text-sm font-medium mb-1">หมวดหมู่</label>
                                        <div style={{ display: 'flex', gap: '0.5rem' }}>
                                            <select
                                                value={formData.category}
                                                onChange={e => setFormData({ ...formData, category: e.target.value })}
                                                className="w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-green-500"
                                                required
                                            >
                                                <option value="">-- เลือกหมวดหมู่ --</option>
                                                {categories.map(cat => (
                                                    <option key={cat.id} value={cat.name}>{cat.name}</option>
                                                ))}
                                            </select>
                                            <Button type="button" variant="outline" onClick={() => setIsCategoryModalOpen(true)} title="เพิ่มหมวดหมู่ใหม่">+</Button>
                                        </div>
                                    </div>
    */

    // ...

    const [searchQuery, setSearchQuery] = useState('');
    const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' } | null>(null);
    const [filteredTrees, setFilteredTrees] = useState<Tree[]>([]);
    const [priceFilter, setPriceFilter] = useState({ min: '', max: '' });

    useEffect(() => {
        filterAndSortTrees();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [trees, searchQuery, sortConfig, priceFilter]);

    const filterAndSortTrees = () => {
        let result = [...trees];

        // Filter by search query
        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            result = result.filter(t =>
                t.name.toLowerCase().includes(query) ||
                t.category.toLowerCase().includes(query) ||
                t.tags?.some(tag => tag.toLowerCase().includes(query))
            );
        }

        // Filter by price range
        if (priceFilter.min) {
            result = result.filter(t => t.price >= Number(priceFilter.min));
        }
        if (priceFilter.max) {
            result = result.filter(t => t.price <= Number(priceFilter.max));
        }

        // Sort
        if (sortConfig) {
            result.sort((a, b) => {
                let aValue: string | number = 0;
                let bValue: string | number = 0;

                switch (sortConfig.key) {
                    case 'name':
                        aValue = a.name;
                        bValue = b.name;
                        break;
                    case 'category':
                        aValue = a.category;
                        bValue = b.category;
                        break;
                    case 'price':
                        aValue = a.price;
                        bValue = b.price;
                        break;
                    case 'status':
                        // Sort by status priority: Out (0) < Low (1) < Available (2)
                        const aAvail = (a.stock || 0) - (a.reserved || 0);
                        const bAvail = (b.stock || 0) - (b.reserved || 0);

                        const getStatusValue = (avail: number) => {
                            if (avail <= 0) return 0; // Out of stock
                            if (avail < 5) return 1;  // Low stock
                            return 2;                 // Available
                        };

                        aValue = getStatusValue(aAvail);
                        bValue = getStatusValue(bAvail);
                        break;
                    case 'stock':
                        aValue = a.stock || 0;
                        bValue = b.stock || 0;
                        break;
                    default:
                        return 0;
                }

                if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });
        }

        setFilteredTrees(result);
    };

    const handleSort = (key: string) => {
        setSortConfig(current => {
            if (current?.key === key) {
                return { key, direction: current.direction === 'asc' ? 'desc' : 'asc' };
            }
            return { key, direction: 'asc' };
        });
    };

    const fetchTrees = async () => {
        try {
            const res = await fetch('/api/trees');
            if (res.ok) {
                const data = await res.json();
                setTrees(data);
            }
        } catch (error) {
            console.error('Failed to fetch trees', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('คุณแน่ใจหรือไม่ที่จะลบต้นไม้นี้?')) return;

        try {
            const res = await fetch(`/api/trees/${id}`, { method: 'DELETE' });
            if (res.ok) {
                fetchTrees();
            }
        } catch (error) {
            console.error('Failed to delete', error);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const payload = {
            ...formData,
            images: formData.images, // Already an array
            tags: formData.tags
        };

        try {
            let res;
            if (editingTree) {
                res = await fetch(`/api/trees/${editingTree.id}`, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
            } else {
                res = await fetch('/api/trees', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
            }

            if (res.ok) {
                alert(editingTree ? 'แก้ไขข้อมูลต้นไม้เรียบร้อยแล้ว' : 'เพิ่มต้นไม้ใหม่เรียบร้อยแล้ว');
                setIsModalOpen(false);
                setEditingTree(null);
                resetForm();
                fetchTrees();
            } else {
                const errorData = await res.json();
                alert(`เกิดข้อผิดพลาด: ${errorData.error || 'ไม่สามารถบันทึกข้อมูลได้'}`);
            }
        } catch (error) {
            console.error('Failed to save', error);
            alert('เกิดข้อผิดพลาดในการเชื่อมต่อกับเซิร์ฟเวอร์');
        }
    };

    const resetForm = () => {
        setFormData({ name: '', description: '', price: 0, category: '', images: [], tags: [], growthTime: '', isPromotion: false, originalPrice: 0, promotionName: '', promotionEndDate: '', stock: 0 });
    };

    const openEdit = (tree: Tree) => {
        setEditingTree(tree);
        setFormData({
            name: tree.name,
            description: tree.description,
            price: tree.price,
            category: tree.category,
            images: tree.images || [],
            tags: tree.tags || [],
            growthTime: tree.growthTime || '',
            isPromotion: tree.isPromotion || false,
            originalPrice: tree.originalPrice || 0,
            promotionName: tree.promotionName || '',
            promotionEndDate: tree.promotionEndDate ? new Date(tree.promotionEndDate).toISOString().split('T')[0] : '',
            stock: tree.stock || 0
        });
        setIsModalOpen(true);
    };

    const openAdd = () => {
        setEditingTree(null);
        resetForm();
        setIsModalOpen(true);
    };

    const removeImage = (indexToRemove: number) => {
        setFormData(prev => ({
            ...prev,
            images: prev.images.filter((_, index) => index !== indexToRemove)
        }));
    };

    // Show loading state while checking auth
    if (isAuthLoading) {
        return <div className="flex justify-center items-center min-h-screen">กำลังโหลด...</div>;
    }

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                <h1 style={{ fontSize: '2rem', fontWeight: 'bold' }}>จัดการต้นไม้ (Manage Trees)</h1>
                <Button variant="primary" onClick={openAdd}>+ เพิ่มต้นไม้ใหม่</Button>
            </div>

            {/* Search and Filters */}
            <div style={{ display: 'flex', gap: '1rem', marginBottom: '1rem', alignItems: 'flex-end' }}>
                <div style={{ flex: 1 }}>
                    <SearchBar
                        placeholder="ค้นหาชื่อต้นไม้, หมวดหมู่, tags..."
                        onSearch={setSearchQuery}
                    />
                </div>
                <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <input
                        type="number"
                        placeholder="ราคาต่ำสุด"
                        value={priceFilter.min}
                        onChange={(e) => setPriceFilter({ ...priceFilter, min: e.target.value })}
                        style={{ padding: '0.5rem', borderRadius: '0.5rem', border: '1px solid #d1d5db', width: '120px' }}
                    />
                    <input
                        type="number"
                        placeholder="ราคาสูงสุด"
                        value={priceFilter.max}
                        onChange={(e) => setPriceFilter({ ...priceFilter, max: e.target.value })}
                        style={{ padding: '0.5rem', borderRadius: '0.5rem', border: '1px solid #d1d5db', width: '120px' }}
                    />
                </div>
            </div>

            <Card>
                <CardContent style={{ padding: 0 }}>
                    <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '800px' }}>
                        <thead style={{ backgroundColor: '#f9fafb', borderBottom: '1px solid #e5e7eb' }}>
                            <tr>
                                <th style={{ padding: '1rem' }}>รูปภาพ</th>
                                <SortableTableHeader
                                    label="ชื่อ"
                                    sortKey="name"
                                    currentSort={sortConfig}
                                    onSort={handleSort}
                                />
                                <SortableTableHeader
                                    label="หมวดหมู่"
                                    sortKey="category"
                                    currentSort={sortConfig}
                                    onSort={handleSort}
                                />
                                <th style={{ padding: '1rem' }}>Tags</th>
                                <th style={{ padding: '1rem' }}>ระยะเวลา</th>
                                <SortableTableHeader
                                    label="ราคา"
                                    sortKey="price"
                                    currentSort={sortConfig}
                                    onSort={handleSort}
                                />
                                <th style={{ padding: '1rem' }}>จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {isLoading ? (
                                <tr><td colSpan={7} style={{ padding: '2rem', textAlign: 'center' }}>กำลังโหลด...</td></tr>
                            ) : filteredTrees.length === 0 ? (
                                <tr><td colSpan={7} style={{ padding: '2rem', textAlign: 'center' }}>ไม่พบข้อมูลต้นไม้</td></tr>
                            ) : (
                                filteredTrees.map(tree => (
                                    <tr key={tree.id} style={{ borderBottom: '1px solid #e5e7eb' }}>
                                        <td style={{ padding: '1rem' }}>
                                            <img src={tree.images[0] || '/placeholder-tree.jpg'} alt={tree.name} style={{ width: '50px', height: '50px', objectFit: 'cover', borderRadius: '0.25rem' }} />
                                            {tree.images.length > 1 && <span className="text-xs text-gray-500 ml-1">+{tree.images.length - 1}</span>}
                                        </td>
                                        <td style={{ padding: '1rem', fontWeight: 500 }}>{tree.name}</td>
                                        <td style={{ padding: '1rem' }}>{tree.category}</td>
                                        <td style={{ padding: '1rem' }}>
                                            <div className="flex flex-wrap gap-1">
                                                {tree.tags?.slice(0, 3).map(t => (
                                                    <span key={t} className="text-xs bg-gray-100 px-1 rounded">{t}</span>
                                                ))}
                                                {tree.tags?.length > 3 && <span className="text-xs text-gray-500">+{tree.tags.length - 3}</span>}
                                            </div>
                                        </td>
                                        <td style={{ padding: '1rem' }}>{tree.growthTime || '-'}</td>
                                        <td style={{ padding: '1rem' }}>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                                <span>฿{tree.price.toLocaleString()}</span>
                                                {tree.isPromotion && (
                                                    <span style={{ backgroundColor: '#fee2e2', color: '#dc2626', padding: '0.125rem 0.375rem', borderRadius: '9999px', fontSize: '0.625rem', fontWeight: 'bold' }}>SALE</span>
                                                )}
                                            </div>
                                        </td>
                                        <td style={{ padding: '1rem' }}>
                                            <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                                                <Button size="sm" variant="outline" onClick={() => openEdit(tree)}>แก้ไข</Button>
                                                <Button size="sm" variant="outline" onClick={() => handleDelete(tree.id)} style={{ borderColor: '#ef4444', color: '#ef4444' }}>ลบ</Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </CardContent>
            </Card>

            {/* Modal */}
            {isModalOpen && (
                <div style={{
                    position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
                    backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 50
                }}>
                    <Card style={{ width: '90%', maxWidth: '600px', maxHeight: '90vh', overflowY: 'auto' }}>
                        <CardHeader>
                            <CardTitle>{editingTree ? 'แก้ไขต้นไม้' : 'เพิ่มต้นไม้ใหม่'}</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                                <Input label="ชื่อต้นไม้" value={formData.name} onChange={e => setFormData({ ...formData, name: e.target.value })} required />
                                <div>
                                    <label style={{ display: 'block', marginBottom: '0.5rem', fontSize: '0.875rem', fontWeight: 500 }}>รายละเอียด</label>
                                    <textarea
                                        value={formData.description}
                                        onChange={e => setFormData({ ...formData, description: e.target.value })}
                                        style={{ width: '100%', padding: '0.75rem', borderRadius: '0.5rem', border: '1px solid #d1d5db' }}
                                        rows={3}
                                        required
                                    />
                                </div>
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '1rem' }}>
                                    <Input label="ราคา (บาท)" type="number" value={formData.price} onChange={e => setFormData({ ...formData, price: Number(e.target.value) })} required />
                                    <Input label="สต็อกสินค้า" type="number" value={formData.stock || 0} onChange={e => setFormData({ ...formData, stock: Number(e.target.value) })} required />

                                    <div>
                                        <label className="block text-sm font-medium mb-1">หมวดหมู่</label>
                                        <div style={{ display: 'flex', gap: '0.5rem' }}>
                                            <select
                                                value={formData.category}
                                                onChange={e => setFormData({ ...formData, category: e.target.value })}
                                                className="w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-green-500"
                                                required
                                                style={{ flex: 1 }}
                                            >
                                                <option value="">-- เลือกหมวดหมู่ --</option>
                                                {categories.map(cat => (
                                                    <option key={cat.id} value={cat.name}>{cat.name}</option>
                                                ))}
                                            </select>
                                            <Button type="button" variant="outline" onClick={() => setIsCategoryModalOpen(true)} title="เพิ่มหมวดหมู่ใหม่" style={{ fontSize: '1.25rem', padding: '0 1rem' }}>+</Button>
                                        </div>
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium mb-1">ระยะเวลาเติบโต</label>
                                    <select
                                        value={formData.growthTime}
                                        onChange={e => setFormData({ ...formData, growthTime: e.target.value })}
                                        className="w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-green-500"
                                    >
                                        <option value="">-- ไม่ระบุ --</option>
                                        <optgroup label="เป็นอาทิตย์">
                                            <option value="1 อาทิตย์">1 อาทิตย์</option>
                                            <option value="2 อาทิตย์">2 อาทิตย์</option>
                                            <option value="3 อาทิตย์">3 อาทิตย์</option>
                                            <option value="4 อาทิตย์">4 อาทิตย์</option>
                                        </optgroup>
                                        <optgroup label="เป็นเดือน">
                                            <option value="1 เดือน">1 เดือน</option>
                                            <option value="2 เดือน">2 เดือน</option>
                                            <option value="3 เดือน">3 เดือน</option>
                                            <option value="4 เดือน">4 เดือน</option>
                                            <option value="5 เดือน">5 เดือน</option>
                                            <option value="6 เดือน">6 เดือน</option>
                                            <option value="7 เดือน">7 เดือน</option>
                                            <option value="8 เดือน">8 เดือน</option>
                                            <option value="9 เดือน">9 เดือน</option>
                                            <option value="10 เดือน">10 เดือน</option>
                                            <option value="11 เดือน">11 เดือน</option>
                                            <option value="12 เดือน">12 เดือน</option>
                                        </optgroup>
                                    </select>
                                </div>
                                <div className="space-y-2">
                                    <label className="block text-sm font-medium">รูปภาพ ({formData.images.length} รูป)</label>
                                    <label
                                        style={{
                                            border: '2px dashed #d1d5db',
                                            borderRadius: '0.5rem',
                                            padding: '1.5rem',
                                            textAlign: 'center',
                                            display: 'block',
                                            cursor: 'pointer',
                                            backgroundColor: '#f9fafb',
                                            transition: 'all 0.2s'
                                        }}
                                        className="hover:bg-gray-100 dark:hover:bg-gray-800"
                                    >
                                        <input
                                            type="file"
                                            accept="image/*"
                                            multiple
                                            style={{ display: 'none' }}
                                            onChange={async (e) => {
                                                const files = e.target.files;
                                                if (!files || files.length === 0) return;

                                                const uploadFormData = new FormData();
                                                for (let i = 0; i < files.length; i++) {
                                                    uploadFormData.append('images', files[i]);
                                                }

                                                try {
                                                    const res = await fetch('/api/upload/images', {
                                                        method: 'POST',
                                                        body: uploadFormData
                                                    });
                                                    if (res.ok) {
                                                        const data = await res.json();
                                                        if (data.urls) {
                                                            setFormData(prev => ({ ...prev, images: [...prev.images, ...data.urls] }));
                                                        } else if (data.url) {
                                                            // Fallback for single file response just in case
                                                            setFormData(prev => ({ ...prev, images: [...prev.images, data.url] }));
                                                        }
                                                    } else {
                                                        alert('Upload failed');
                                                    }
                                                } catch (error) {
                                                    console.error('Error uploading:', error);
                                                    alert('Error uploading file');
                                                }
                                            }}
                                        />
                                        <div>
                                            <div style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>📷</div>
                                            <p className="text-sm text-gray-500 font-medium">คลิกเพื่อเพิ่มรูปภาพ (เลือกได้หลายรูป)</p>
                                            <p className="text-xs text-gray-400 mt-1">PNG, JPG up to 5MB</p>
                                        </div>
                                    </label>

                                    {/* Image Previews */}
                                    {formData.images.length > 0 && (
                                        <div className="grid grid-cols-4 gap-2 mt-4">
                                            {formData.images.map((imgUrl, index) => (
                                                <div key={index} className="relative group" style={{ width: '100px', height: '100px', border: '1px solid #e5e7eb', borderRadius: '0.5rem', overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f9fafb' }}>
                                                    <img
                                                        src={imgUrl}
                                                        alt={`Preview ${index}`}
                                                        style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain' }}
                                                    />
                                                    <button
                                                        type="button"
                                                        onClick={() => removeImage(index)}
                                                        className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 w-6 h-6 flex items-center justify-center text-xs opacity-0 group-hover:opacity-100 transition-opacity"
                                                        title="ลบรูปนี้"
                                                        style={{ cursor: 'pointer' }}
                                                    >
                                                        ✕
                                                    </button>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>

                                <div>
                                    <label className="block text-sm font-medium mb-1">Tags</label>
                                    <TagInput
                                        value={formData.tags}
                                        onChange={tags => setFormData({ ...formData, tags })}
                                        suggestions={allTags}
                                    />
                                </div>

                                {/* Promotion Section */}
                                <div style={{ borderTop: '1px solid #e5e7eb', paddingTop: '1rem', marginTop: '0.5rem' }}>
                                    <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer', marginBottom: '1rem' }}>
                                        <input
                                            type="checkbox"
                                            checked={formData.isPromotion}
                                            onChange={e => setFormData({ ...formData, isPromotion: e.target.checked })}
                                            style={{ width: '18px', height: '18px', accentColor: '#dc2626' }}
                                        />
                                        <span style={{ fontWeight: 'bold', color: '#dc2626' }}>🔥 เปิดโปรโมชั่น</span>
                                    </label>

                                    {formData.isPromotion && (
                                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem', padding: '1rem', backgroundColor: '#fef2f2', borderRadius: '0.5rem', border: '1px solid #fecaca' }}>
                                            <Input label="ราคาเดิม (บาท)" type="number" value={formData.originalPrice} onChange={e => setFormData({ ...formData, originalPrice: Number(e.target.value) })} />
                                            <Input label="ชื่อโปรโมชั่น" value={formData.promotionName} onChange={e => setFormData({ ...formData, promotionName: e.target.value })} placeholder="เช่น ลดราคาต้อนรับปีใหม่" />
                                            <Input label="วันหมดเขต" type="date" value={formData.promotionEndDate} onChange={e => setFormData({ ...formData, promotionEndDate: e.target.value })} />
                                            {formData.originalPrice > 0 && formData.price > 0 && (
                                                <p style={{ fontSize: '0.875rem', color: '#dc2626', fontWeight: 'bold' }}>
                                                    💰 ลด {Math.round(((formData.originalPrice - formData.price) / formData.originalPrice) * 100)}% (จาก ฿{formData.originalPrice.toLocaleString()} เหลือ ฿{formData.price.toLocaleString()})
                                                </p>
                                            )}
                                        </div>
                                    )}
                                </div>

                                <div style={{ display: 'flex', gap: '1rem', justifyContent: 'flex-end', marginTop: '1rem' }}>
                                    <Button type="button" variant="outline" onClick={() => setIsModalOpen(false)}>ยกเลิก</Button>
                                    <Button type="submit" variant="primary">บันทึก</Button>
                                </div>
                            </form>
                        </CardContent>
                    </Card>
                </div>
            )}

            {/* Category Modal */}
            {isCategoryModalOpen && (
                <div style={{
                    position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
                    backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 60
                }}>
                    <Card style={{ width: '90%', maxWidth: '400px', backgroundColor: 'white' }}>
                        <CardHeader>
                            <CardTitle>เพิ่มหมวดหมู่ใหม่</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <form onSubmit={handleAddCategory} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                                <Input
                                    label="ชื่อหมวดหมู่"
                                    value={newCategoryName}
                                    onChange={e => setNewCategoryName(e.target.value)}
                                    placeholder="เช่น ไม้มงคล, ไม้ประดับ"
                                    required
                                />
                                <div style={{ display: 'flex', gap: '0.5rem', justifyContent: 'flex-end' }}>
                                    <Button type="button" variant="outline" onClick={() => setIsCategoryModalOpen(false)}>ยกเลิก</Button>
                                    <Button type="submit" variant="primary">บันทึก</Button>
                                </div>
                            </form>
                        </CardContent>
                    </Card>
                </div>
            )}
        </div>
    );
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

// GET - Fetch all reviews for admin (including hidden)
export async function GET() {
    try {
        const reviews = await prisma.review.findMany({
            include: {
                user: {
                    select: { id: true, firstName: true, lastName: true, email: true }
                },
                tree: {
                    select: { id: true, name: true, images: true }
                }
            },
            orderBy: { createdAt: 'desc' }
        });

        return NextResponse.json(reviews);
    } catch (error) {
        console.error('Error fetching admin reviews:', error);
        return NextResponse.json({ error: 'Failed to fetch reviews' }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET() {
    try {
        // Get best-selling trees of all time based on completed bookings
        const bestSellingData = await prisma.bookingItem.groupBy({
            by: ['treeId'],
            where: {
                booking: {
                    status: 'COMPLETED'
                }
            },
            _sum: {
                quantity: true
            },
            orderBy: {
                _sum: {
                    quantity: 'desc'
                }
            }
        });

        // Get tree details for each best-selling tree
        const treeIds = bestSellingData.map(item => item.treeId);
        const trees = await prisma.tree.findMany({
            where: {
                id: {
                    in: treeIds
                }
            }
        });

        // Sort trees by sales quantity
        const sortedTrees = trees.sort((a, b) => {
            const aData = bestSellingData.find(item => item.treeId === a.id);
            const bData = bestSellingData.find(item => item.treeId === b.id);
            const aQuantity = aData?._sum.quantity || 0;
            const bQuantity = bData?._sum.quantity || 0;
            return bQuantity - aQuantity;
        });

        return NextResponse.json(sortedTrees);
    } catch (error) {
        console.error('Error fetching overall best sellers:', error);
        return NextResponse.json({ error: 'Failed to fetch overall best sellers' }, { status: 500 });
