            {!user && (
                <div style={{ backgroundColor: '#fef3c7', color: '#92400e', padding: '1rem', borderRadius: '0.5rem', marginBottom: '2rem' }}>
                    ⚠️ กรุณา <Link href="/login" style={{ textDecoration: 'underline', fontWeight: 'bold' }}>เข้าสู่ระบบ</Link> ก่อนยืนยันการจอง
                </div>
            )}

            {user && !user.verified && (
                <div style={{ backgroundColor: '#fef2f2', color: '#991b1b', padding: '1rem', borderRadius: '0.5rem', marginBottom: '2rem', display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '0.5rem' }}>
                    <span>📧 กรุณายืนยันอีเมลก่อนทำการจอง</span>
                    <Link href="/verify-email" style={{ backgroundColor: '#dc2626', color: 'white', padding: '0.375rem 1rem', borderRadius: '0.375rem', fontWeight: 'bold', textDecoration: 'none', fontSize: '0.875rem' }}>
                        ยืนยันอีเมล
                    </Link>
                </div>
            )}

            <div className="grid-cart">
                {/* Item List */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                    {items.map((item) => (
                        <Card key={item.instanceId} style={{ display: 'flex', flexDirection: 'column', padding: '1rem' }}>
                            <div style={{ display: 'flex', flexDirection: 'row', alignItems: 'center' }}>
                                <div style={{ width: '80px', height: '80px', backgroundColor: '#f9fafb', borderRadius: '0.375rem', flexShrink: 0, padding: '0.25rem', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1px solid #e5e7eb' }}>
                                    <img
                                        src={item.images?.[0] || '/placeholder-tree.jpg'}
                                        alt={item.name}
                                        style={{ width: '100%', height: '100%', objectFit: 'contain' }}
                                    />
                                </div>
                                <div style={{ marginLeft: '1rem', flexGrow: 1 }}>
                                    <h3 style={{ fontWeight: 'bold' }}>{item.name}</h3>
                                    <p style={{ color: '#6b7280', fontSize: '0.875rem' }}>{item.category}</p>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.5rem' }}>
                                        <p style={{ color: 'var(--primary)', fontWeight: 'bold' }}>฿ {item.price.toLocaleString()}</p>

                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', border: '1px solid #e5e7eb', borderRadius: '4px', padding: '2px' }}>
                                            <button
                                                onClick={() => updateQuantity(item.instanceId, -1)}
                                                style={{ padding: '0 8px', background: 'none', border: 'none', cursor: 'pointer', fontSize: '1.25rem', color: item.quantity === 1 ? '#d1d5db' : 'inherit' }}
                                                disabled={item.quantity <= 1}
                                            >
                                                -
                                            </button>
                                            <span style={{ minWidth: '20px', textAlign: 'center', fontWeight: 'bold' }}>{item.quantity}</span>
                                            <button
                                                onClick={() => updateQuantity(item.instanceId, 1)}
                                                style={{ padding: '0 8px', background: 'none', border: 'none', cursor: 'pointer', fontSize: '1.25rem' }}
                                            >
                                                +
                                            </button>
                                        </div>
                                    </div>
                                </div>
                                <div style={{ marginLeft: '1rem' }}>
                                    <Button variant="ghost" size="sm" onClick={() => removeItem(item.instanceId)} style={{ color: '#ef4444' }}>
                                        ลบ
                                    </Button>
                                </div>
                            </div>

                            <div style={{ marginTop: '1rem', paddingTop: '1rem', borderTop: '1px solid #f3f4f6' }}>
                                <label style={{ display: 'block', marginBottom: '0.5rem', fontSize: '0.875rem', fontWeight: '500' }}>
                                    วันรับสินค้า (สำหรับรายการนี้)
                                </label>
                                {(() => {
                                    // Calculate min date based on stock and growth time
                                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                                    const availableStock: number = (item as any).stock - ((item as any).reserved || 0); // CartItem doesn't directly type stock/reserved, assuming it's passed from Tree

                                    const minItemDate = new Date();
                                    let daysToAdd = 0;

                                    if (availableStock < item.quantity) {
                                        // Not enough stock, use growth time (default 2 weeks if not specified or unparseable)
                                        daysToAdd = 14;
                                        if (item.growthTime) {
                                            const match = item.growthTime.match(/(\d+)\s*(อาทิตย์|เดือน)/);
                                            if (match) {
                                                const value = parseInt(match[1]);
                                                daysToAdd = match[2] === 'เดือน' ? value * 30 : value * 7;
                                            }
                                        }
                                    }

                                    minItemDate.setDate(new Date().getDate() + daysToAdd);
                                    const minItemDateString = minItemDate.toISOString().split('T')[0];

                                    return (
                                        <>
                                            {daysToAdd > 0 && (
                                                <div style={{ fontSize: '0.75rem', color: '#ea580c', marginBottom: '0.5rem' }}>
                                                    * สินค้าพรีออเดอร์ ต้องรอการเติบโตประมาณ {item.growthTime || '2 อาทิตย์'}
                                                </div>
                                            )}
                                            <Input
                                                type="date"
                                                min={minItemDateString}
                                                required
                                                value={item.pickupDate}
                                                onChange={(e) => updateDate(item.instanceId, e.target.value)}
                                            />
                                            {!item.pickupDate && (
                                                <p style={{ fontSize: '0.75rem', color: '#ef4444', marginTop: '0.25rem' }}>
                                                    * กรุณาระบุวันรับ
                                                </p>
                                            )}
                                        </>
                                    );
                                })()}
                            </div>
                        </Card>
                    ))}
                    <div style={{ marginTop: '1rem' }}>
                        <Link href="/shop"><Button variant="outline">เลือกต้นไม้เพิ่ม</Button></Link>
                    </div>
                </div>

                {/* Summary & Booking Form */}
                <div>

                    <Card>
                        <CardHeader>
                            <CardTitle>สรุปรายการจอง</CardTitle>
                        </CardHeader>
                        <CardContent>
                            <form onSubmit={handleBooking}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                                    <span>จำนวนต้นไม้รวม</span>
                                    <span>{items.reduce((acc, i) => acc + i.quantity, 0)} ต้น</span>
                                </div>
                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                                    <span>ราคารวม</span>
                                    <span>฿ {totalPrice.toLocaleString()}</span>
                                </div>

                                {/* Payment Type Selector */}
                                <div style={{ marginTop: '1rem', marginBottom: '1rem', padding: '1rem', backgroundColor: '#f9fafb', borderRadius: '0.5rem' }}>
                                    <label style={{ display: 'block', marginBottom: '0.75rem', fontWeight: '600', fontSize: '0.875rem' }}>
                                        เลือกประเภทการชำระเงิน:
                                    </label>
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                                        <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', padding: '0.75rem', backgroundColor: paymentType === 'deposit' ? '#e0f2fe' : 'white', border: `2px solid ${paymentType === 'deposit' ? 'var(--primary)' : '#e5e7eb'}`, borderRadius: '0.5rem', transition: 'all 0.2s' }}>
                                            <input
                                                type="radio"
                                                name="paymentType"
                                                value="deposit"
                                                checked={paymentType === 'deposit'}
                                                onChange={(e) => setPaymentType(e.target.value as 'deposit' | 'full')}
                                                style={{ marginRight: '0.75rem' }}
                                            />
                                            <div style={{ flex: 1 }}>
                                                <div style={{ fontWeight: '600' }}>ชำระมัดจำ 30%</div>
                                                <div style={{ fontSize: '0.875rem', color: '#6b7280' }}>฿{(totalPrice * 0.3).toLocaleString()}</div>
                                            </div>
                                        </label>
                                        <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', padding: '0.75rem', backgroundColor: paymentType === 'full' ? '#e0f2fe' : 'white', border: `2px solid ${paymentType === 'full' ? 'var(--primary)' : '#e5e7eb'}`, borderRadius: '0.5rem', transition: 'all 0.2s' }}>
                                            <input
                                                type="radio"
                                                name="paymentType"
                                                value="full"
                                                checked={paymentType === 'full'}
                                                onChange={(e) => setPaymentType(e.target.value as 'deposit' | 'full')}
                                                style={{ marginRight: '0.75rem' }}
                                            />
                                            <div style={{ flex: 1 }}>
                                                <div style={{ fontWeight: '600' }}>ชำระเต็มจำนวน 100%</div>
                                                <div style={{ fontSize: '0.875rem', color: '#6b7280' }}>฿{totalPrice.toLocaleString()}</div>
                                            </div>
                                        </label>
                                    </div>
                                </div>

                                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '1rem', paddingTop: '1rem', borderTop: '1px solid #e5e7eb', fontWeight: 'bold' }}>
                                    <span>{paymentType === 'full' ? 'ยอดชำระทั้งหมด' : 'มัดจำที่ต้องชำระ (30%)'}</span>
                                    <span style={{ color: 'var(--primary)', fontSize: '1.25rem' }}>฿ {deposit.toLocaleString()}</span>
                                </div>

                                <div style={{ marginTop: '1rem', marginBottom: '1rem', fontSize: '0.875rem', color: '#6b7280' }}>
                                    เงื่อนไข: ต้องชำระมัดจำภายใน 24 ชม. หลังทำรายการ
                                </div>

                                <Button fullWidth type="submit" size="lg" disabled={!canSubmit}>
                                    {canSubmit ? 'ยืนยันการจอง' : 'กรุณาระบุวันให้ครบ'}
                                </Button>
                            </form>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/AuthContext';
import { useCart } from '@/lib/CartContext';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import FavoriteButton from '@/components/FavoriteButton';
import Link from 'next/link';

interface Tree {
    id: string;
    name: string;
    description: string;
    price: number;
    category: string;
    status: string;
    images: string[];
    tags: string[];
    growthTime?: string | null;
}

interface Favorite {
    id: string;
    treeId: string;
    tree: Tree;
    createdAt: string;
}

export default function FavoritesPage() {
    const router = useRouter();
    const { user, isLoading: isAuthLoading } = useAuth();
    const { addItem } = useCart();
    const [favorites, setFavorites] = useState<Favorite[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        if (isAuthLoading) return;
        if (!user) {
            router.push('/login');
            return;
        }

        fetchFavorites();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user, isAuthLoading, router]);

    const fetchFavorites = async () => {
        try {
            const res = await fetch('/api/favorites', {
                headers: {
                    'x-user-id': user?.id || ''
                }
            });
            if (res.ok) {
                const data = await res.json();
                setFavorites(data);
            }
        } catch (error) {
            console.error('Failed to fetch favorites:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const removeFavorite = async (treeId: string) => {
        try {
            const res = await fetch(`/api/favorites?treeId=${treeId}`, {
                method: 'DELETE',
                headers: {
                    'x-user-id': user?.id || ''
                }
            });
            if (res.ok) {
                setFavorites(favorites.filter(f => f.treeId !== treeId));
            }
        } catch (error) {
            console.error('Failed to remove favorite:', error);
        }
    };

    const handleAddToCart = (tree: Tree) => {
        addItem(tree, 1);
        alert('เพิ่มลงตะกร้าเรียบร้อย!');
    };

    if (isAuthLoading || isLoading) {
        return (
            <div className="container" style={{ padding: '4rem 1rem', textAlign: 'center' }}>
                <p>กำลังโหลด...</p>
            </div>
        );
    }

    return (
        <div className="container" style={{ padding: '4rem 1rem' }}>
            <h1 style={{ fontSize: '2.5rem', marginBottom: '2rem', textAlign: 'center' }}>
                ❤️ รายการโปรดของฉัน
            </h1>

            {favorites.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '4rem 1rem' }}>
                    <p style={{ fontSize: '1.25rem', color: '#6b7280', marginBottom: '1rem' }}>
                        ยังไม่มีรายการโปรด
                    </p>
                    <p style={{ color: '#9ca3af', marginBottom: '2rem' }}>
                        คลิกไอคอนหัวใจที่สินค้าที่คุณชอบเพื่อบันทึกไว้ที่นี่
                    </p>
                    <Link href="/shop">
                        <Button variant="primary">ไปเลือกสินค้า</Button>
                    </Link>
                </div>
            ) : (
                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
                    gap: '2rem'
                }}>
                    {favorites.map(favorite => (
                        <Card key={favorite.id} style={{ position: 'relative' }}>
                            <CardContent style={{ padding: '1rem' }}>
                                {/* Favorite Button */}
                                <div style={{
                                    position: 'absolute',
                                    top: '1rem',
                                    right: '1rem',
                                    zIndex: 10
                                }}>
                                    <FavoriteButton
                                        treeId={favorite.treeId}
                                        initialIsFavorite={true}
                                        onToggle={(isFav) => {
                                            if (!isFav) removeFavorite(favorite.treeId);
                                        }}
                                        size="md"
                                    />
                                </div>

                                {/* Image */}
                                <Link href={`/shop/${favorite.tree.id}`}>
                                    <div style={{
                                        backgroundColor: '#f3f4f6',
                                        borderRadius: '0.5rem',
                                        overflow: 'hidden',
                                        marginBottom: '1rem',
                                        aspectRatio: '1/1',
                                        cursor: 'pointer'
                                    }}>
                                        <img
                                            src={(() => {
                                                let imageUrl = '/placeholder-tree.jpg';
                                                if (favorite.tree.images) {
                                                    if (Array.isArray(favorite.tree.images)) {
                                                        imageUrl = favorite.tree.images[0] || '/placeholder-tree.jpg';
                                                    } else if (typeof favorite.tree.images === 'string') {
                                                        try {
                                                            const images = JSON.parse(favorite.tree.images);
                                                            imageUrl = images[0] || '/placeholder-tree.jpg';
                                                        } catch {
                                                            imageUrl = '/placeholder-tree.jpg';
                                                        }
                                                    }
                                                }
                                                return imageUrl;
                                            })()}
                                            alt={favorite.tree.name}
                                            style={{
                                                width: '100%',
                                                height: '100%',
                                                objectFit: 'contain'
                                            }}
                                        />
                                    </div>
                                </Link>

                                {/* Details */}
                                <Link href={`/shop/${favorite.tree.id}`} style={{ textDecoration: 'none', color: 'inherit' }}>
                                    <h3 style={{ fontSize: '1.125rem', fontWeight: 600, marginBottom: '0.5rem' }}>
                                        {favorite.tree.name}
                                    </h3>
                                </Link>

                                <p style={{ fontSize: '1.25rem', fontWeight: 'bold', color: 'var(--primary)', marginBottom: '1rem' }}>
                                    ฿{favorite.tree.price.toLocaleString()}
                                </p>


                                {/* Tags */}
                                <div style={{ display: 'flex', gap: '0.25rem', flexWrap: 'wrap', marginBottom: '1rem' }}>
                                    {(() => {
                                        let tags: string[] = [];
                                        if (favorite.tree.tags) {
                                            if (Array.isArray(favorite.tree.tags)) {
                                                tags = favorite.tree.tags;
                                            } else if (typeof favorite.tree.tags === 'string') {
                                                try {
                                                    tags = JSON.parse(favorite.tree.tags);
                                                } catch {
                                                    tags = [];
                                                }
                                            }
                                        }
                                        return tags.slice(0, 3).map(tag => (
                                            <span
                                                key={tag}
                                                style={{
                                                    backgroundColor: '#f3f4f6',
                                                    padding: '0.25rem 0.5rem',
                                                    borderRadius: '9999px',
                                                    fontSize: '0.75rem'
                                                }}
                                            >
                                                #{tag}
                                            </span>
                                        ));
                                    })()}
                                </div>

                                {/* Add to cart button */}
                                {favorite.tree.status === 'AVAILABLE' ? (
                                    <Button
                                        fullWidth
                                        variant="primary"
                                        onClick={() => handleAddToCart(favorite.tree)}
                                    >
                                        เพิ่มลงตะกร้า
                                    </Button>
                                ) : (
                                    <Button fullWidth variant="outline" disabled>
                                        สินค้าถูกจองแล้ว
                                    </Button>
                                )}
                            </CardContent>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/AuthContext';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import Link from 'next/link';

interface BookingItem {
    id: string;
    treeId: string;
    quantity: number;
    price: number;
    tree: {
        name: string;
        images: string;
    };
}

interface Booking {
    id: string;
    refCode: string;
    status: string;
    totalPrice: number;
    deposit: number;
    pickupDate: string;
    note: string | null;
    slipUrl: string | null;
    createdAt: string;
    items: BookingItem[];
}

export default function MyOrdersPage() {
    const router = useRouter();
    const { user, isLoading: isAuthLoading } = useAuth();
    const [bookings, setBookings] = useState<Booking[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [uploadingSlip, setUploadingSlip] = useState<string | null>(null);

    useEffect(() => {
        if (isAuthLoading) return;
        if (!user) {
            router.push('/login');
            return;
        }

        fetchBookings();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user, isAuthLoading, router]);

    const fetchBookings = async () => {
        if (!user) return;
        try {
            const res = await fetch(`/api/bookings?userId=${user.id}`);
            if (res.ok) {
                const data = await res.json();
                setBookings(data);
            }
        } catch (error) {
            console.error('Failed to fetch bookings', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSlipUpload = async (bookingId: string, file: File) => {
        console.log('🔵 handleSlipUpload called', { bookingId, fileName: file?.name });

        if (!file) {
            console.log('❌ No file provided');
            return;
        }

        console.log('📁 File info:', {
            name: file.name,
            type: file.type,
            size: file.size,
            sizeInMB: (file.size / 1024 / 1024).toFixed(2) + ' MB'
        });

        // Validate file type
        if (!file.type.startsWith('image/')) {
            console.log('❌ Invalid file type:', file.type);
            alert('กรุณาอัปโหลดไฟล์รูปภาพเท่านั้น');
            return;
        }

        // Validate file size (max 5MB)
        if (file.size > 5 * 1024 * 1024) {
            console.log('❌ File too large:', file.size);
            alert('ไฟล์มีขนาดใหญ่เกินไป (สูงสุด 5MB)');
            return;
        }

        console.log('✅ File validation passed');
        setUploadingSlip(bookingId);

        try {
            console.log('🔄 Starting file conversion to base64...');
            // Convert to base64
            const reader = new FileReader();
            reader.onloadend = async () => {
                const base64String = reader.result as string;
                console.log('✅ Base64 conversion complete, length:', base64String.length);

                // Update booking with slip URL
                console.log('📤 Sending PATCH request to:', `/api/bookings/${bookingId}`);
                const res = await fetch(`/api/bookings/${bookingId}`, {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ slipUrl: base64String })
                });

                console.log('📥 Response status:', res.status, res.statusText);

                if (res.ok) {
                    const data = await res.json();
                    console.log('✅ Upload successful!', data);
                    alert('อัปโหลดสลิปสำเร็จ! รอการตรวจสอบจากทางร้าน');
                    fetchBookings();
                } else {
                    const errorText = await res.text();
                    console.error('❌ Upload failed:', res.status, errorText);
                    alert('เกิดข้อผิดพลาดในการอัปโหลดสลิป');
                }
                setUploadingSlip(null);
            };

            reader.onerror = (error) => {
                console.error('❌ FileReader error:', error);
                alert('เกิดข้อผิดพลาดในการอ่านไฟล์');
                setUploadingSlip(null);
            };

            reader.readAsDataURL(file);
        } catch (error) {
            console.error('❌ Failed to upload slip', error);
            alert('เกิดข้อผิดพลาดในการเชื่อมต่อ');
            setUploadingSlip(null);
        }
    };

    const getStatusBadge = (status: string) => {
        const colors: Record<string, string> = {
            PENDING: '#f59e0b',
            PAID: '#3b82f6',
            PREPARING: '#8b5cf6',
            READY: '#22c55e',
            COMPLETED: '#6b7280',
            CANCELLED: '#ef4444'
        };
        return {
            backgroundColor: colors[status] || '#6b7280',
            color: 'white',
            padding: '0.5rem 1rem',
            borderRadius: '9999px',
            fontSize: '0.875rem',
            fontWeight: 'bold',
            display: 'inline-block'
        };
    };

    const getStatusText = (status: string) => {
        const texts: Record<string, string> = {
            PENDING: 'รอชำระเงิน',
            PAID: 'ชำระแล้ว',
            PREPARING: 'กำลังเตรียมต้นไม้',
            READY: 'พร้อมรับได้แล้ว',
            COMPLETED: 'เสร็จสิ้น',
            CANCELLED: 'ยกเลิก'
        };
        return texts[status] || status;
    };

    const getStatusIcon = (status: string) => {
        const icons: Record<string, string> = {
            PENDING: '⏳',
            PAID: '💰',
            PREPARING: '🌱',
            READY: '✅',
            COMPLETED: '🎉',
            CANCELLED: '❌'
        };
        return icons[status] || '📦';
    };

    if (isAuthLoading || isLoading) {
        return (
            <div className="container" style={{ padding: '4rem 1rem', textAlign: 'center' }}>
                <p>กำลังโหลด...</p>
            </div>
        );
    }

    return (
        <div className="container" style={{ padding: '2rem 1rem' }}>
            <h1 style={{ fontSize: '2rem', fontWeight: 'bold', marginBottom: '2rem' }}>ออเดอร์ของฉัน</h1>

