                                        {firstImage && (
                                            <div style={{
                                                backgroundColor: '#f9fafb',
                                                borderRadius: '0.5rem',
                                                padding: '1rem',
                                                display: 'flex',
                                                alignItems: 'center',
                                                justifyContent: 'center'
                                            }}>
                                                <img
                                                    src={firstImage}
                                                    alt="Tree"
                                                    style={{
                                                        maxWidth: '100%',
                                                        maxHeight: '150px',
                                                        objectFit: 'contain'
                                                    }}
                                                />
                                            </div>
                                        )}

                                        {/* Details */}
                                        <div>
                                            <h3 style={{ fontWeight: 'bold', marginBottom: '0.75rem' }}>รายการสินค้า:</h3>
                                            {booking.items.map((item, idx) => (
                                                <div key={idx} style={{ marginBottom: '0.5rem' }}>
                                                    • {item.tree.name} x{item.quantity} - ฿{item.price.toLocaleString()}
                                                </div>
                                            ))}

                                            <div style={{ marginTop: '1rem', paddingTop: '1rem', borderTop: '1px solid #e5e7eb' }}>
                                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                                                    <span>ยอดรวม:</span>
                                                    <span style={{ fontWeight: 'bold' }}>฿{booking.totalPrice.toLocaleString()}</span>
                                                </div>
                                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                                                    <span>มัดจำ (30%):</span>
                                                    <span style={{ color: 'var(--primary)' }}>฿{booking.deposit.toLocaleString()}</span>
                                                </div>
                                                <div style={{ display: 'flex', justifyContent: 'space-between', fontWeight: 'bold', fontSize: '1.125rem', marginTop: '0.75rem' }}>
                                                    <span>วันรับของ:</span>
                                                    <span style={{ color: 'var(--secondary)' }}>
                                                        {new Date(booking.pickupDate).toLocaleDateString('th-TH')}
                                                    </span>
                                                </div>
                                            </div>

                                            {/* Payment Info */}
                                            {booking.status === 'PENDING' && (
                                                <div style={{
                                                    marginTop: '1rem',
                                                    padding: '1rem',
                                                    backgroundColor: '#fef3c7',
                                                    borderRadius: '0.5rem',
                                                    border: '2px solid #fbbf24'
                                                }}>
                                                    <h4 style={{ fontWeight: 'bold', marginBottom: '0.75rem', color: '#92400e' }}>
                                                        💰 ข้อมูลการชำระเงิน
                                                    </h4>

                                                    {/* PromptPay QR Code */}
                                                    <div style={{
                                                        backgroundColor: '#f0f9ff',
                                                        padding: '1rem',
                                                        borderRadius: '0.5rem',
                                                        marginBottom: '1rem',
                                                        border: '2px solid #0ea5e9',
                                                        textAlign: 'center'
                                                    }}>
                                                        <p style={{ fontWeight: 'bold', marginBottom: '0.5rem', color: '#0369a1', fontSize: '0.875rem' }}>
                                                            💳 สแกน QR Code เพื่อชำระเงิน
                                                        </p>
                                                        <div style={{
                                                            backgroundColor: 'white',
                                                            padding: '0.75rem',
                                                            borderRadius: '0.5rem',
                                                            display: 'inline-block',
                                                            boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
                                                        }}>
                                                            <img
                                                                src={`https://promptpay.io/0616900908/${booking.deposit}.png`}
                                                                alt="PromptPay QR Code"
                                                                style={{
                                                                    width: '200px',
                                                                    height: '200px',
                                                                    display: 'block'
                                                                }}
                                                            />
                                                        </div>
                                                        <p style={{ fontSize: '0.75rem', color: '#6b7280', marginTop: '0.5rem' }}>
                                                            สแกนด้วยแอพธนาคารเพื่อชำระ ฿{booking.deposit.toLocaleString()}
                                                        </p>
                                                    </div>

                                                    {/* Bank Transfer Details */}
                                                    <div style={{ fontSize: '0.875rem', color: '#78350f' }}>
                                                        <p style={{ fontSize: '0.75rem', color: '#6b7280', marginBottom: '0.5rem', textAlign: 'center' }}>
                                                            หรือโอนเงินผ่านบัญชีธนาคาร
                                                        </p>
                                                        <p style={{ marginBottom: '0.25rem' }}>ธนาคาร: <strong>ไทยพาณิชย์</strong></p>
                                                        <p style={{ marginBottom: '0.25rem' }}>เลขที่บัญชี: <strong>123-456-7890</strong></p>
                                                        <p style={{ marginBottom: '0.25rem' }}>ชื่อบัญชี: <strong>คุณแดงการ์เด้น</strong></p>
                                                        <p style={{ marginTop: '0.5rem', fontWeight: 'bold' }}>
                                                            ยอดที่ต้องชำระ: ฿{booking.deposit.toLocaleString()}
                                                        </p>
                                                    </div>
                                                </div>
                                            )}

                                            {/* Slip Upload Section */}
                                            {booking.status === 'PENDING' && !booking.slipUrl && (
                                                <div style={{ marginTop: '1rem' }}>
                                                    <label
                                                        htmlFor={`slip-upload-${booking.id}`}
                                                        style={{
                                                            display: 'block',
                                                            width: '100%',
                                                            padding: '0.75rem',
                                                            backgroundColor: '#10b981',
                                                            color: 'white',
                                                            borderRadius: '0.5rem',
                                                            textAlign: 'center',
                                                            cursor: uploadingSlip === booking.id ? 'not-allowed' : 'pointer',
                                                            fontWeight: 'bold',
                                                            opacity: uploadingSlip === booking.id ? 0.6 : 1
                                                        }}
                                                    >
                                                        {uploadingSlip === booking.id ? '⏳ กำลังอัปโหลด...' : '📤 อัปโหลดสลิปการโอนเงิน'}
                                                    </label>
                                                    <input
                                                        id={`slip-upload-${booking.id}`}
                                                        type="file"
                                                        accept="image/*"
                                                        style={{ display: 'none' }}
                                                        onChange={(e) => {
                                                            const file = e.target.files?.[0];
                                                            if (file) handleSlipUpload(booking.id, file);
                                                        }}
                                                        disabled={uploadingSlip === booking.id}
                                                    />
                                                </div>
                                            )}

                                            {/* Show uploaded slip */}
                                            {booking.slipUrl && (
                                                <div style={{
                                                    marginTop: '1rem',
                                                    padding: '1rem',
                                                    backgroundColor: '#f0fdf4',
                                                    borderRadius: '0.5rem',
                                                    border: '2px solid #10b981'
                                                }}>
                                                    <h4 style={{ fontWeight: 'bold', marginBottom: '0.5rem', color: '#065f46' }}>
                                                        ✅ สลิปการโอนเงิน
                                                    </h4>
                                                    <img
                                                        src={booking.slipUrl}
                                                        alt="Payment Slip"
                                                        style={{
                                                            maxWidth: '100%',
                                                            maxHeight: '300px',
                                                            objectFit: 'contain',
                                                            borderRadius: '0.375rem',
                                                            border: '1px solid #d1d5db',
                                                            cursor: 'pointer'
                                                        }}
                                                        onClick={() => window.open(booking.slipUrl!, '_blank')}
                                                    />
                                                    <p style={{ fontSize: '0.75rem', color: '#065f46', marginTop: '0.5rem', textAlign: 'center' }}>
                                                        คลิกที่รูปเพื่อดูขนาดเต็ม
                                                    </p>
                                                </div>
                                            )}

                                            {booking.note && (
                                                <div style={{
                                                    marginTop: '1rem',
                                                    padding: '0.75rem',
                                                    backgroundColor: '#fef3c7',
                                                    borderRadius: '0.375rem',
                                                    fontSize: '0.875rem'
                                                }}>
                                                    <strong>หมายเหตุจากร้าน:</strong> {booking.note}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

import { Button } from '@/components/ui/Button';
import { Card, CardContent } from '@/components/ui/Card';
import Link from 'next/link';
import { ArrowRight, Leaf, ShieldCheck, Truck, Percent, Heart } from 'lucide-react';
import { prisma } from '@/lib/prisma';
import { ScrollAnimation } from '@/components/ScrollAnimation';
import { ParallaxSection } from '@/components/ParallaxSection';
import FavoriteButton from '@/components/FavoriteButton';
import { ImageSlider } from '@/components/ImageSlider';
import InlineEdit from '@/components/InlineEdit';
import { User } from 'lucide-react';

export const dynamic = 'force-dynamic';

export default async function Home() {
  const featuredTrees = await prisma.tree.findMany({
    take: 4,
    orderBy: { createdAt: 'desc' }
  });

  // Top 5 best sellers
  const bestSellingData = await prisma.bookingItem.groupBy({
    by: ['treeId'],
    where: { booking: { status: 'COMPLETED' } },
    _sum: { quantity: true },
    orderBy: { _sum: { quantity: 'desc' } },
    take: 5
  });

  const bestSellingTreeIds = bestSellingData.map((d: { treeId: string }) => d.treeId);
  const bestSellingTrees = await prisma.tree.findMany({
    where: { id: { in: bestSellingTreeIds } }
  });

  const bestSellingTreesWithCount = bestSellingTrees.map(tree => {
    const saleData = bestSellingData.find((d: { treeId: string, _sum: { quantity: number | null } }) => d.treeId === tree.id);
    return {
      ...tree,
      soldCount: saleData?._sum.quantity || 0
    };
  }).sort((a, b) => b.soldCount - a.soldCount);

  // Fallback if no sales
  const displayBestSellers = bestSellingTreesWithCount.length > 0 ? bestSellingTreesWithCount : featuredTrees;

  // Weekly Best Sellers
  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

  const weeklyBestSellingData = await prisma.bookingItem.groupBy({
    by: ['treeId'],
    where: {
      booking: {
        status: 'COMPLETED',
        createdAt: { gte: sevenDaysAgo }
      }
    },
    _sum: { quantity: true },
    orderBy: { _sum: { quantity: 'desc' } },
    take: 5
  });

  const weeklyBestSellingTreeIds = weeklyBestSellingData.map((d: { treeId: string }) => d.treeId);
  const weeklyBestSellingTrees = await prisma.tree.findMany({
    where: { id: { in: weeklyBestSellingTreeIds } }
  });

  const weeklyBestSellingTreesWithCount = weeklyBestSellingTrees.map(tree => {
    const saleData = weeklyBestSellingData.find((d: { treeId: string, _sum: { quantity: number | null } }) => d.treeId === tree.id);
    return {
      ...tree,
      soldCount: saleData?._sum.quantity || 0
    };
  }).sort((a, b) => b.soldCount - a.soldCount);


  // Promotional trees
  const promotionalTrees = await prisma.tree.findMany({
    where: {
      isPromotion: true,
      OR: [
        { promotionEndDate: null },
        { promotionEndDate: { gte: new Date() } }
      ]
    },
    take: 4,
    orderBy: { updatedAt: 'desc' }
  });

  // Seasonal/Festival trees (e.g. Valentine's / Rose)
  const seasonalTrees = await prisma.tree.findMany({
    where: {
      OR: [
        { tags: { contains: 'วาเลนไทน์' } },
        { name: { contains: 'กุหลาบ' } },
        { tags: { contains: 'เทศกาล' } }
      ],
      stock: { gt: 0 }
    },
    take: 4
  });

  // Get Kwak Phra Phrom for Hero Section
  const heroTree = await prisma.tree.findFirst({
    where: { name: 'กวักพระพรหม' }
  });

  // Fetch Site Settings
  const settings = await prisma.siteSetting.findMany();
  const settingsMap = settings.reduce((acc: Record<string, string>, curr: { key: string, value: string }) => {
    acc[curr.key] = curr.value;
    return acc;
  }, {});

  const heroTitle = settingsMap['hero_title'] || 'สวนสวยเริ่มต้นที่ สวนคุณแดง';
  const heroTitleColor = settingsMap['hero_title_color'] || 'var(--foreground)';
  const heroTitleSize = settingsMap['hero_title_fontSize'] || 'clamp(1.75rem, 8vw, 4.5rem)';

  const heroSubtitle = settingsMap['hero_subtitle'] || 'ค้นพบความสุขในการปลูกต้นไม้กับเรา แหล่งรวมพันธุ์ไม้คัดพิเศษ\nพร้อมคำแนะนำจากผู้เชี่ยวชาญ เพื่อสวนสวยในบ้านคุณ';
  const heroSubtitleColor = settingsMap['hero_subtitle_color'] || '#6b7280';
  const heroSubtitleSize = settingsMap['hero_subtitle_fontSize'] || 'clamp(0.9rem, 3vw, 1.1rem)';

  const heroTag = settingsMap['hero_tag'] || '#ต้นไม้คุณภาพ จากคุณแดง';
  const heroTagColor = settingsMap['hero_tag_color'] || '#6b7280';
  const heroTagSize = settingsMap['hero_tag_fontSize'] || '0.9rem';

  const valTitle = settingsMap['valentine_title'] || 'มอบความรัก\nส่งต่อต้นไม้';
  const valTitleColor = settingsMap['valentine_title_color'] || '#991b1b';
  const valTitleSize = settingsMap['valentine_title_fontSize'] || 'clamp(1.75rem, 5vw, 3.5rem)';

  const valSubtitle = settingsMap['valentine_subtitle'] || 'หลงรักต้นไม้มงคล ที่พร้อมเบ่งบานในฤดูกาลนี้';
  const valSubtitleColor = settingsMap['valentine_subtitle_color'] || '#b91c1c';
  const valSubtitleSize = settingsMap['valentine_subtitle_fontSize'] || 'clamp(0.9rem, 2vw, 1.25rem)';

  // Fetch real reviews for Testimonials section
  const topReviews = await prisma.review.findMany({
    where: {
      rating: { gte: 4 }, // 4 or 5 stars
      hidden: false,
      comment: { not: null, notIn: [''] }
    },
    include: {
      user: {
        select: { firstName: true, lastName: true }
      }
    },
    orderBy: { createdAt: 'desc' },
    take: 4 // Max 4 reviews displayed on the homepage
  });

  return (
    <main>
      {/* Hero Section */}
      <section style={{
        position: 'relative',
        backgroundColor: '#fefcf9',
        padding: '4rem 0 6rem',
        overflow: 'hidden'
      }}>
        {/* Background Decorative Circle */}
        <div style={{
          position: 'absolute',
          top: '-10%',
          right: '-10%',
          width: '600px',
          height: '600px',
          backgroundColor: '#e6f5e6',
          borderRadius: '50%',
          zIndex: 0
        }}></div>

        <div className="container grid-hero" style={{ position: 'relative', zIndex: 1 }}>
          {/* Text Content */}
          <ScrollAnimation animation="fade-up">
            <div style={{ gridColumn: 'span 1', position: 'relative' }}>
              <InlineEdit
                settingKey="hero_tag"
                initialValue={heroTag}
                allowStyleEdit
                initialColor={heroTagColor}
                initialBgColor={settingsMap['hero_tag_bgColor']}
                initialFontSize={heroTagSize}
                renderAs="span"
                style={{ color: heroTagColor, background: settingsMap['hero_tag_bgColor'] || 'transparent', fontSize: heroTagSize, letterSpacing: '2px', textTransform: 'uppercase', marginBottom: '1rem', display: 'inline-block', padding: '0.25rem 0.5rem', borderRadius: '0.25rem' }}
              />
              <InlineEdit
                settingKey="hero_title"
                initialValue={heroTitle}
                allowStyleEdit
                initialColor={heroTitleColor}
                initialBgColor={settingsMap['hero_title_bgColor']}
                initialFontSize={heroTitleSize}
                renderAs="h1"
                useSpecialTitleFormat
                style={{
                  fontFamily: 'var(--font-playfair), serif',
                  fontSize: heroTitleSize,
                  fontWeight: '700',
                  lineHeight: '1.2',
                  color: heroTitleColor,
                  background: settingsMap['hero_title_bgColor'] || 'transparent',
                  marginBottom: '1rem',
                  wordBreak: 'break-word',
                  overflowWrap: 'break-word',
                  display: 'inline-block',
                  padding: '0.25rem 0.5rem',
                  borderRadius: '0.5rem'
                }}
              />
              <InlineEdit
                settingKey="hero_subtitle"
                initialValue={heroSubtitle}
                allowStyleEdit
                initialColor={heroSubtitleColor}
                initialBgColor={settingsMap['hero_subtitle_bgColor']}
                initialFontSize={heroSubtitleSize}
                renderAs="p"
                multiline
                style={{ fontSize: heroSubtitleSize, color: heroSubtitleColor, background: settingsMap['hero_subtitle_bgColor'] || 'transparent', marginBottom: '2.5rem', lineHeight: '1.6', whiteSpace: 'pre-line', padding: '0.25rem 0.5rem', borderRadius: '0.5rem', display: 'inline-block' }}
              />
              <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
                <Link href="/shop">
                  <Button size="lg" style={{
                    backgroundColor: 'var(--primary)',
                    color: 'white',
                    borderRadius: '50px',
                    padding: '0 2rem'
                  }}>
                    จองต้นไม้ →
                  </Button>
                </Link>
                <Link href="/services">
                  <Button size="lg" variant="outline" style={{
                    borderRadius: '50px',
                    padding: '0 2rem',
                    borderColor: 'var(--foreground)',
                    color: 'var(--foreground)'
                  }}>
                    บริการของเรา →
                  </Button>
                </Link>
              </div>
            </div>
          </ScrollAnimation>

          {/* Image Content with Parallax */}
          <ParallaxSection speed={0.3}>
            <div style={{ position: 'relative', display: 'flex', justifyContent: 'center' }}>
              <div style={{
                width: '100%',
                maxWidth: '400px',
                height: 'min(500px, 100vw)',
                backgroundColor: '#e5e7eb',
                borderRadius: '20px',
                backgroundImage: 'url("/images/products/kwak-phra-phrom.jpg")',
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)'
              }}></div>

              {/* Floating Cards simulating the template */}
              <Link href={heroTree ? `/trees/${heroTree.id}` : "/shop?q=กวักพระพรหม"} style={{ textDecoration: 'none', color: 'inherit' }}>
                <div style={{
                  position: 'absolute',
                  bottom: '10%',
                  left: '0',
                  transform: 'translateX(-10px)',
                  backgroundColor: 'white',
                  padding: '1rem',
                  borderRadius: '12px',
                  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '1rem',
                  cursor: 'pointer',
                  transition: 'transform 0.2s',
                }}
                  className="hover:scale-105"
                >
                  <div style={{ width: '50px', height: '50px', borderRadius: '8px', overflow: 'hidden' }}>
                    <img src="/images/products/kwak-phra-phrom.jpg" alt="กวักพระพรหม" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                  </div>
                  <div>
                    <div style={{ fontWeight: 'bold', fontSize: '0.9rem' }}>กวักพระพรหม</div>
                    <div style={{ fontSize: '0.8rem', color: '#166534' }}>฿350.00</div>
                  </div>
                </div>
              </Link>
            </div>
          </ParallaxSection>
        </div>
      </section>

      {/* Best Sellers Slider */}
      <section className="container" style={{ margin: '-3rem auto 0', position: 'relative', zIndex: 10, display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 400px), 1fr))', gap: '2rem', paddingBottom: '4rem' }}>
        {weeklyBestSellingTreesWithCount.length > 0 && (
          <ScrollAnimation animation="fade-up" delay={100} style={{ height: '100%' }}>
            <ImageSlider trees={weeklyBestSellingTreesWithCount} title="ขายดีสัปดาห์นี้" subtitle="Weekly Best Sellers" />
          </ScrollAnimation>
        )}
        <ScrollAnimation animation="fade-up" delay={150} style={{ height: '100%' }}>
          {displayBestSellers.length > 0 && (
            <ImageSlider trees={displayBestSellers} title="ขายดีตลอดกาล" subtitle="All Time Best Sellers" />
