                                                </div>
                                            )}

                                            {/* Slip Upload Section */}
                                            <div style={{
                                                marginTop: '1rem',
                                                padding: '1rem',
                                                backgroundColor: '#f0fdf4',
                                                borderRadius: '0.5rem',
                                                border: '1px solid #bbf7d0'
                                            }}>
