                    <Link href="/best-sellers" style={{ textDecoration: 'none' }}>
                        <div style={{
                            backgroundColor: '#fef3c7',
                            borderRadius: '16px',
                            padding: '2rem',
                            color: '#433422',
                            display: 'flex',
                            justifyContent: 'space-between',
                            alignItems: 'center',
                            minHeight: '200px',
