                            </a>
                        </div>
                    </div>
                </div>
            </header>

            {/* Mobile Bottom Navigation */}
            <div className={styles.mobileBottomNav}>
                <Link href="/" className={styles.mobileNavLink}>
                    <Home size={24} />
                    <span>หน้าแรก</span>
                </Link>
                <Link href="/shop" className={styles.mobileNavLink}>
                    <Package size={24} />
                    <span>สินค้า</span>
                </Link>
                <Link href="/cart" className={styles.mobileNavLink}>
