                        <Bell size={24} />
                        {unreadCount > 0 && (
                            <span className={styles.mobileNavBadge}>{unreadCount}</span>
                        )}
                    </div>
                    <span>แจ้งเตือน</span>
                </Link>
                <Link href={user ? "/profile" : "/login"} className={styles.mobileNavLink}>
                    <User size={24} />
                    <span>บัญชี</span>
                </Link>
            </div>
        </>
    );
}

'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';

interface PaymentModalProps {
    isOpen: boolean;
    onClose: () => void;
    onUpload: (file: File) => void;
}

export default function PaymentModal({ isOpen, onClose, onUpload }: PaymentModalProps) {
    const [preview, setPreview] = useState<string | null>(null);
    const [fileName, setFileName] = useState<string>('');
    const [selectedFile, setSelectedFile] = useState<File | null>(null);

    if (!isOpen) return null;

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setSelectedFile(file);
            setFileName(file.name);
            const reader = new FileReader();
            reader.onloadend = () => {
                setPreview(reader.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSubmit = () => {
        if (selectedFile) {
            onUpload(selectedFile);
        }
    };

    return (
        <div style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 50
        }}>
            <Card style={{ width: '90%', maxWidth: '400px', backgroundColor: 'white' }}>
                <CardHeader>
                    <CardTitle>แนบสลิปการโอนเงิน</CardTitle>
                </CardHeader>
                <CardContent>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                        <div style={{
                            border: '2px dashed #d1d5db', borderRadius: '0.5rem', padding: '2rem',
                            textAlign: 'center', cursor: 'pointer', position: 'relative'
                        }}>
                            <input
                                type="file"
                                accept="image/*"
                                onChange={handleFileChange}
                                style={{
                                    position: 'absolute', top: 0, left: 0, width: '100%', height: '100%',
                                    opacity: 0, cursor: 'pointer'
                                }}
                            />
                            {preview ? (
                                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                                    <img src={preview} alt="Slip Preview" style={{ maxHeight: '200px', objectFit: 'contain', marginBottom: '0.5rem' }} />
                                    <p style={{ fontSize: '0.875rem', color: '#6b7280' }}>{fileName}</p>
                                </div>
                            ) : (
                                <div>
                                    <p style={{ marginBottom: '0.5rem', fontSize: '2rem' }}>📎</p>
                                    <p style={{ color: '#4b5563' }}>คลิกเพื่อเลือกรูปภาพ</p>
                                    <p style={{ fontSize: '0.75rem', color: '#9ca3af' }}>JPG, PNG (Max 5MB)</p>
                                </div>
                            )}
                        </div>

                        <div style={{ display: 'flex', gap: '0.5rem', justifyContent: 'flex-end', marginTop: '1rem' }}>
                            <Button variant="outline" onClick={onClose}>ยกเลิก</Button>
                            <Button variant="primary" onClick={handleSubmit} disabled={!preview}>ยืนยันการแนบสลิป</Button>
                        </div>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

'use client';

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import Link from 'next/link';
import { useCart } from '@/lib/CartContext';
import { useAuth } from '@/lib/AuthContext';
import { useState, useEffect } from 'react';
import ImageGallery from './ImageGallery';
import StarRating from './StarRating';
import ReviewList from './ReviewList';
import FavoriteButton from './FavoriteButton';

interface Tree {
    id: string;
    name: string;
    description: string;
    price: number;
    category: string;
    status: string;
    images: string[];
    tags: string[];
    growthTime?: string | null;
    rating?: number;
    reviewCount?: number;
    isPromotion?: boolean;
    originalPrice?: number | null;
    promotionName?: string | null;
    promotionEndDate?: string | null;
}

export default function ProductDetail({ tree }: { tree: Tree }) {
    const { addItem } = useCart();
    const { user } = useAuth();
    const [quantity, setQuantity] = useState(1);
    const [isAdded, setIsAdded] = useState(false);

    // Calculate available stock
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const stock = (tree as any).stock || 0;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const reserved = (tree as any).reserved || 0;
    const availableStock = Math.max(0, stock - reserved);
    const isOutOfStock = availableStock === 0;

    const handleAdd = () => {
        // ไม่ต้องเช็คสต๊อก - ให้สั่งซื้อได้แม้หมด (จะกลายเป็น PENDING_APPROVAL)
        addItem(tree, quantity);
        setIsAdded(true);
        setTimeout(() => setIsAdded(false), 2000);
    };

    const handleQuantityChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        let val = parseInt(e.target.value);
        if (isNaN(val) || val < 1) {
            val = 1;
        }
        setQuantity(val);
    };

    return (
        <div className="container" style={{ padding: '2rem 1rem' }}>
            <Link href="/shop" style={{ display: 'inline-block', marginBottom: '1rem', color: '#6b7280' }}>
                ← กลับไปหน้าร้านค้า
            </Link>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '2rem' }}>
                {/* Left: Image Gallery */}
                <div>
                    <ImageGallery images={tree.images} alt={tree.name} />
                </div>

                {/* Right: Details & Booking */}
                <div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.5rem' }}>
                        <h1 style={{ fontSize: '2rem', flex: 1 }}>{tree.name}</h1>

                        {/* Favorite Button */}
                        <div style={{ marginLeft: '1rem' }}>
                            <FavoriteButton treeId={tree.id} size="lg" />
                        </div>
                    </div>

                    {/* Price with promotion support */}
                    <div style={{ marginBottom: '1rem' }}>
                        {tree.isPromotion && tree.originalPrice && tree.originalPrice > tree.price ? (
                            <>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.25rem' }}>
                                    <span style={{ fontSize: '1.75rem', fontWeight: 'bold', color: '#dc2626' }}>
                                        ฿{tree.price.toLocaleString()}
                                    </span>
                                    <span style={{ fontSize: '1.125rem', color: '#9ca3af', textDecoration: 'line-through' }}>
                                        ฿{tree.originalPrice.toLocaleString()}
                                    </span>
                                    <span style={{
                                        backgroundColor: '#dc2626', color: 'white',
                                        padding: '0.125rem 0.5rem', borderRadius: '9999px',
                                        fontSize: '0.75rem', fontWeight: 'bold'
                                    }}>
                                        -{Math.round(((tree.originalPrice - tree.price) / tree.originalPrice) * 100)}%
                                    </span>
                                </div>
                                {tree.promotionName && (
                                    <span style={{
                                        display: 'inline-block',
                                        backgroundColor: '#fef3c7', color: '#92400e',
                                        padding: '0.25rem 0.75rem', borderRadius: '9999px',
                                        fontSize: '0.75rem', fontWeight: 'bold', marginBottom: '0.25rem'
                                    }}>
                                        🔥 {tree.promotionName}
                                    </span>
                                )}
                                {tree.promotionEndDate && (
                                    <p style={{ fontSize: '0.75rem', color: '#dc2626', marginTop: '0.25rem' }}>
                                        ⏰ หมดเขต {new Date(tree.promotionEndDate).toLocaleDateString('th-TH', { day: 'numeric', month: 'long', year: 'numeric' })}
                                    </p>
                                )}
                            </>
                        ) : (
                            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', color: 'var(--primary)' }}>
                                ฿ {tree.price.toLocaleString()}
                            </p>
                        )}
                    </div>

                    {tree.growthTime && (
                        <p style={{ marginBottom: '1rem', color: '#4b5563' }}>
                            <strong>ระยะเวลาเติบโต:</strong> {tree.growthTime}
                        </p>
                    )}


                    <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', marginBottom: '1.5rem' }}>
                        {(() => {
                            let tags: string[] = [];
                            if (tree.tags) {
                                if (Array.isArray(tree.tags)) {
                                    tags = tree.tags;
                                } else if (typeof tree.tags === 'string') {
                                    try {
                                        tags = JSON.parse(tree.tags);
                                    } catch {
                                        tags = [];
                                    }
                                }
                            }
                            return tags.map(tag => (
                                <span key={tag} style={{ backgroundColor: '#f3f4f6', padding: '0.25rem 0.75rem', borderRadius: '9999px', fontSize: '0.875rem' }}>
                                    #{tag}
                                </span>
                            ));
                        })()}
                    </div>


                    <p style={{ marginBottom: '2rem', lineHeight: '1.6' }}>
                        {tree.description}
                    </p>

                    <Card>
                        <CardHeader>
                            <CardTitle>สั่งจอง</CardTitle>
                        </CardHeader>
                        <CardContent>
                            {tree.status === 'AVAILABLE' ? (
                                <div>
                                    {/* Stock warning for out-of-stock items */}
                                    {isOutOfStock && (
                                        <div style={{
                                            backgroundColor: '#fef3c7',
                                            color: '#92400e',
                                            padding: '0.75rem',
                                            borderRadius: '0.375rem',
                                            marginBottom: '1rem',
                                            fontSize: '0.875rem',
                                            border: '1px solid #fbbf24'
                                        }}>
                                            ⚠️ <strong>สินค้าหมดสต๊อก</strong> - คุณยังสามารถสั่งจองได้ โดยจะรอการ<strong>อนุมัติจากแอดมิน</strong>เมื่อมีสินค้าเข้า
                                        </div>
                                    )}

                                    <div style={{ marginBottom: '1rem' }}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                                            <label style={{ fontSize: '0.875rem' }}>จำนวน</label>
                                            <span style={{
                                                fontSize: '0.875rem',
                                                color: isOutOfStock ? '#dc2626' : '#6b7280',
                                                fontWeight: isOutOfStock ? 'bold' : 'normal'
                                            }}>
                                                {isOutOfStock ? 'หมดสต๊อก - จองได้' : `มีสินค้า ${availableStock} ต้น`}
                                            </span>
                                        </div>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                            <Button variant="outline" onClick={() => setQuantity(q => Math.max(1, q - 1))} disabled={quantity <= 1}>-</Button>
                                            <input
                                                type="number"
                                                min="1"
                                                value={quantity}
                                                onChange={handleQuantityChange}
                                                style={{
                                                    fontSize: '1.25rem',
                                                    fontWeight: 'bold',
                                                    width: '60px',
                                                    textAlign: 'center',
                                                    border: '1px solid #d1d5db',
                                                    borderRadius: '0.375rem',
                                                    padding: '0.25rem',
                                                }}
                                            />
                                            <Button variant="outline" onClick={() => setQuantity(q => q + 1)}>+</Button>
                                        </div>
                                    </div>

                                    <Button fullWidth onClick={handleAdd} variant="primary">
                                        {isAdded ? '✓ เพิ่มเรียบร้อย!' : `เพิ่มลงตะกร้า (${quantity} ต้น)`}
                                    </Button>
                                </div>
                            ) : (
                                <div style={{ textAlign: 'center', padding: '2rem 0' }}>
                                    <p style={{ color: '#d97706', fontWeight: 'bold' }}>สินค้านี้ถูกจองแล้ว</p>
                                    <p style={{ fontSize: '0.875rem', color: '#6b7280' }}>กรุณาเลือกดูรายการอื่น</p>
                                </div>
                            )}
                        </CardContent>
                    </Card>
                </div>
            </div>

            {/* Reviews Section */}
            <div style={{ marginTop: '3rem' }}>
                <div style={{ marginBottom: '2rem' }}>
                    <h2 style={{ fontSize: '1.75rem', fontWeight: 'bold', marginBottom: '0.5rem' }}>
                        รีวิวและคะแนน
                    </h2>
                    {tree.rating !== undefined && tree.reviewCount !== undefined && tree.reviewCount > 0 && (
                        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                            <StarRating rating={tree.rating} readonly size="md" />
                            <span style={{ fontSize: '1.25rem', fontWeight: 600, color: '#374151' }}>
                                {tree.rating.toFixed(1)}
                            </span>
                            <span style={{ fontSize: '0.875rem', color: '#6b7280' }}>
                                ({tree.reviewCount} รีวิว)
                            </span>
                        </div>
                    )}
                </div>

                <ReviewList treeId={tree.id} currentUserId={user?.id} treeName={tree.name} />
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import StarRating from './StarRating';
import { Button } from './ui/Button';
import ReviewModal from './ReviewModal';

interface Review {
    id: string;
    rating: number;
    comment: string | null;
    images: string | null;
    helpful: number;
    createdAt: string;
    user: {
        id: string;
        firstName: string;
        lastName: string;
    };
    bookingId?: string; // Add bookingId if it exists in response, otherwise it's optional
}

interface ReviewListProps {
    treeId: string;
    currentUserId?: string;
    treeName?: string; // Optional for the modal
}

export default function ReviewList({ treeId, currentUserId, treeName = 'ต้นไม้' }: ReviewListProps) {
    const [reviews, setReviews] = useState<Review[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [sortBy, setSortBy] = useState<'newest' | 'highest' | 'helpful'>('newest');
    const [editingReview, setEditingReview] = useState<Review | null>(null);

    useEffect(() => {
        fetchReviews();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [treeId]);

    const fetchReviews = async () => {
        try {
            const res = await fetch(`/api/reviews?treeId=${treeId}&limit=50`);
            if (res.ok) {
                const data = await res.json();
                setReviews(data.reviews || []);
            }
        } catch (error) {
            console.error('Error fetching reviews:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleHelpful = async (reviewId: string) => {
        try {
            const res = await fetch(`/api/reviews/${reviewId}/helpful`, {
                method: 'POST'
            });
            if (res.ok) {
                // Refresh reviews
                fetchReviews();
            }
        } catch (error) {
            console.error('Error marking helpful:', error);
        }
    };

    const handleDelete = async (reviewId: string) => {
        if (!confirm('ต้องการลบรีวิวนี้หรือไม่?')) return;

        try {
            const res = await fetch(`/api/reviews/${reviewId}`, {
                method: 'DELETE',
                headers: {
                    'x-user-id': currentUserId || '',
                    'x-user-role': 'user'
                }
            });

            if (res.ok) {
                alert('ลบรีวิวสำเร็จ');
                fetchReviews();
            } else {
                const data = await res.json();
                alert(data.error || 'ไม่สามารถลบรีวิวได้');
            }
        } catch (error) {
            console.error('Error deleting review:', error);
            alert('เกิดข้อผิดพลาด');
        }
    };

    const sortedReviews = [...reviews].sort((a, b) => {
        if (sortBy === 'newest') {
            return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        } else if (sortBy === 'highest') {
            return b.rating - a.rating;
        } else {
            return b.helpful - a.helpful;
        }
    });

    if (isLoading) {
        return <p>กำลังโหลดรีวิว...</p>;
    }

    if (reviews.length === 0) {
        return (
            <div style={{ textAlign: 'center', padding: '2rem', color: '#6b7280' }}>
                <p>ยังไม่มีรีวิว</p>
                <p style={{ fontSize: '0.875rem', marginTop: '0.5rem' }}>เป็นคนแรกที่รีวิวสินค้านี้!</p>
            </div>
        );
    }

    return (
        <div>
            {/* Sort Options */}
            <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1rem', flexWrap: 'wrap' }}>
                <span style={{ fontSize: '0.875rem', color: '#6b7280' }}>เรียงตาม:</span>
                <button
                    onClick={() => setSortBy('newest')}
                    style={{
                        fontSize: '0.875rem',
                        fontWeight: sortBy === 'newest' ? 600 : 400,
                        color: sortBy === 'newest' ? 'var(--primary)' : '#6b7280',
                        background: 'none',
                        border: 'none',
                        cursor: 'pointer',
                        textDecoration: sortBy === 'newest' ? 'underline' : 'none'
                    }}
                >
                    ล่าสุด
                </button>
                <span style={{ color: '#d1d5db' }}>|</span>
                <button
                    onClick={() => setSortBy('highest')}
                    style={{
                        fontSize: '0.875rem',
                        fontWeight: sortBy === 'highest' ? 600 : 400,
                        color: sortBy === 'highest' ? 'var(--primary)' : '#6b7280',
                        background: 'none',
                        border: 'none',
                        cursor: 'pointer',
                        textDecoration: sortBy === 'highest' ? 'underline' : 'none'
                    }}
                >
                    คะแนนสูงสุด
                </button>
                <span style={{ color: '#d1d5db' }}>|</span>
                <button
                    onClick={() => setSortBy('helpful')}
                    style={{
                        fontSize: '0.875rem',
                        fontWeight: sortBy === 'helpful' ? 600 : 400,
                        color: sortBy === 'helpful' ? 'var(--primary)' : '#6b7280',
                        background: 'none',
                        border: 'none',
                        cursor: 'pointer',
                        textDecoration: sortBy === 'helpful' ? 'underline' : 'none'
                    }}
                >
                    มีประโยชน์สูงสุด
                </button>
            </div>

            {/* Reviews */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                {sortedReviews.map((review) => {
                    const reviewImages = review.images ? JSON.parse(review.images) : [];

                    return (
                        <div
                            key={review.id}
                            style={{
                                backgroundColor: '#f9fafb',
                                padding: '1.5rem',
                                borderRadius: '0.75rem',
                                border: '1px solid #e5e7eb'
                            }}
                        >
                            {/* Header */}
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.75rem' }}>
                                <div>
                                    <p style={{ fontWeight: 600 }}>{review.user.firstName} {review.user.lastName}</p>
                                    <p style={{ fontSize: '0.75rem', color: '#6b7280' }}>
                                        {new Date(review.createdAt).toLocaleDateString('th-TH', {
                                            year: 'numeric',
                                            month: 'long',
                                            day: 'numeric'
                                        })}
                                    </p>
                                </div>
                                {currentUserId === review.user.id && (
                                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                                        <Button variant="outline" size="sm" onClick={() => setEditingReview(review)}>
                                            แก้ไข
                                        </Button>
                                        <Button variant="outline" size="sm" onClick={() => handleDelete(review.id)}>
                                            ลบ
                                        </Button>
                                    </div>
                                )}
                            </div>

                            {/* Rating */}
                            <StarRating rating={review.rating} readonly size="sm" />

                            {/* Comment */}
                            {review.comment && (
                                <p style={{ marginTop: '0.75rem', lineHeight: '1.6', color: '#374151' }}>
                                    {review.comment}
                                </p>
                            )}

                            {/* Images */}
                            {reviewImages.length > 0 && (
                                <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem', overflowX: 'auto' }}>
                                    {reviewImages.map((img: string, idx: number) => (
                                        <img
                                            key={idx}
                                            src={img}
                                            alt={`Review image ${idx + 1}`}
                                            style={{
                                                width: '100px',
                                                height: '100px',
                                                objectFit: 'cover',
                                                borderRadius: '0.5rem',
                                                cursor: 'pointer'
                                            }}
                                            onClick={() => window.open(img, '_blank')}
                                        />
                                    ))}
                                </div>
                            )}

                            {/* Helpful Button */}
                            <div style={{ marginTop: '1rem' }}>
                                <button
                                    onClick={() => handleHelpful(review.id)}
                                    style={{
                                        fontSize: '0.875rem',
                                        color: '#6b7280',
                                        background: 'none',
                                        border: '1px solid #d1d5db',
                                        borderRadius: '9999px',
                                        padding: '0.25rem 0.75rem',
                                        cursor: 'pointer',
                                        transition: 'all 0.2s'
                                    }}
                                    className="hover:bg-gray-100"
                                >
                                    👍 มีประโยชน์ ({review.helpful})
                                </button>
                            </div>
                        </div>
                    );
                })}
            </div>
            {editingReview && currentUserId && (
                <ReviewModal
                    treeId={treeId}
                    treeName={treeName}
                    userId={currentUserId}
                    reviewId={editingReview.id}
                    initialRating={editingReview.rating}
                    initialComment={editingReview.comment}
                    onClose={() => setEditingReview(null)}
                    onSuccess={() => {
                        fetchReviews();
                        setEditingReview(null);
                    }}
                />
            )}
        </div>
    );
}

'use client';

import { useRouter, useSearchParams } from 'next/navigation';
import { useState } from 'react';

interface ShopControlsProps {
    categories: string[];
}

export function ShopControls({ categories }: ShopControlsProps) {
    const router = useRouter();
    const searchParams = useSearchParams();

    const currentCategory = searchParams.get('category') || '';
    const currentSort = searchParams.get('sort') || 'newest';

    const updateParams = (newParams: Record<string, string | null>) => {
        const params = new URLSearchParams(searchParams.toString());
        Object.entries(newParams).forEach(([key, value]) => {
            if (value === null || value === '') {
                params.delete(key);
            } else {
                params.set(key, value);
            }
        });
        router.push(`/shop?${params.toString()}`);
    };

    return (
        <div style={{ marginBottom: '2rem' }}>
            {/* Sort and Category Filters on Same Line */}
            <div style={{ display: 'flex', gap: '2rem', alignItems: 'center', flexWrap: 'wrap', marginBottom: '1rem' }}>
                {/* Sort Dropdown */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <label style={{ fontSize: '0.875rem', fontWeight: 'bold', color: 'var(--foreground)' }}>เรียงตาม:</label>
                    <select
                        value={currentSort}
                        onChange={(e) => updateParams({ sort: e.target.value })}
                        style={{
                            padding: '0.5rem 1rem',
                            borderRadius: '0.375rem',
                            border: '1px solid var(--border)',
                            backgroundColor: 'white',
                            cursor: 'pointer',
                            fontSize: '0.875rem',
                            color: 'var(--foreground)'
                        }}
                    >
                        <option value="newest">มาใหม่ล่าสุด</option>
                        <option value="price_asc">ราคา: ต่ำ - สูง</option>
                        <option value="price_desc">ราคา: สูง - ต่ำ</option>
                    </select>
                </div>

                {/* Category Filter */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexGrow: 1 }}>
                    <label style={{ fontSize: '0.875rem', fontWeight: 'bold', color: 'var(--foreground)' }}>หมวดหมู่:</label>
                    <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                        <button
                            onClick={() => updateParams({ category: null })}
                            style={{
                                padding: '0.5rem 1rem',
                                borderRadius: '9999px',
                                border: '1px solid',
                                borderColor: currentCategory === '' ? 'var(--primary)' : '#e5e7eb',
                                backgroundColor: currentCategory === '' ? 'var(--primary)' : 'white',
                                color: currentCategory === '' ? 'white' : '#374151',
                                cursor: 'pointer',
                                transition: 'all 0.2s',
                                fontSize: '0.875rem'
                            }}
                        >
                            ทั้งหมด
                        </button>
                        {categories.map((cat) => (
                            <button
                                key={cat}
                                onClick={() => updateParams({ category: cat })}
                                style={{
                                    padding: '0.5rem 1rem',
                                    borderRadius: '9999px',
                                    border: '1px solid',
                                    borderColor: currentCategory === cat ? 'var(--primary)' : '#e5e7eb',
                                    backgroundColor: currentCategory === cat ? 'var(--primary)' : 'white',
                                    color: currentCategory === cat ? 'white' : '#374151',
                                    cursor: 'pointer',
                                    transition: 'all 0.2s',
                                    fontSize: '0.875rem'
                                }}
                            >
                                {cat}
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { Button } from '@/components/ui/Button';

interface SlipViewerProps {
    isOpen: boolean;
    onClose: () => void;
    slipUrl: string | null;
}

export default function SlipViewer({ isOpen, onClose, slipUrl }: SlipViewerProps) {
    if (!isOpen || !slipUrl) return null;

    return (
        <div style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.8)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 60
        }} onClick={onClose}>
            <div style={{ position: 'relative', maxWidth: '90%', maxHeight: '90%' }} onClick={e => e.stopPropagation()}>
                <img src={slipUrl} alt="Payment Slip" style={{ maxWidth: '100%', maxHeight: '80vh', borderRadius: '0.5rem' }} />
                <div style={{ marginTop: '1rem', textAlign: 'center' }}>
                    <Button variant="outline" onClick={onClose} style={{ backgroundColor: 'white' }}>ปิด</Button>
                </div>
            </div>
        </div>
    );
}

